  (1, '2.9.2', '词类', '助词', '动态助词', '动态助词', null, null, '[]'::jsonb, array['了1']::text[], 22, '{}'::text[], '[]'::jsonb, '[]'::jsonb),
  (1, '2.9.3', '词类', '助词', '语气助词', '语气助词', 'frase + 吗 / 吧 / 呢 / 了', 'Estas partículas van al final de la frase y cambian su intención sin tocar el orden de las palabras. 吗 convierte una afirmación en una pregunta de sí o no. 吧 propone algo o pide confirmación. 呢 detrás de un nombre pregunta «¿y…?» (你呢？), y con 在 subraya que algo está pasando ahora. 了 al final indica que la situación ha cambiado: 下雨了 («ya llueve»). Si la frase ya tiene una palabra interrogativa (什么, 哪儿, 谁), no se añade 吗.', '[{"zh":"你是学生吗？","pinyin":"Nǐ shì xuésheng ma?","es":"¿Eres estudiante?"},{"zh":"我们去吃饭吧。","pinyin":"Wǒmen qù chīfàn ba.","es":"Vamos a comer."},{"zh":"我很好，你呢？","pinyin":"Wǒ hěn hǎo, nǐ ne?","es":"Yo estoy bien, ¿y tú?"},{"zh":"他在看书呢。","pinyin":"Tā zài kàn shū ne.","es":"Está leyendo."},{"zh":"下雨了。","pinyin":"Xià yǔ le.","es":"Ya está lloviendo."}]'::jsonb, array['吧1、了2 、吗、呢1、呢2、呢3']::text[], 23, array['吗', '吧', '呢', '了']::text[], '[{"wrong":"你去哪儿吗？","right":"你去哪儿？","why":"Con una palabra interrogativa como 哪儿 la frase ya es una pregunta; añadir 吗 sobra."}]'::jsonb, '[]'::jsonb),
  (1, '2.10', '词类', '叹词', null, '叹词', null, null, '[]'::jsonb, array['喂']::text[], 24, '{}'::text[], '[]'::jsonb, '[]'::jsonb),
  (1, '3.1.1', '短语', '结构类型', '基本结构类型', '基本结构类型', 'A + 和 + B · modificador + núcleo · verbo + objeto · sujeto + predicado', 'Las frases chinas se construyen con cuatro piezas. Unión: dos palabras del mismo tipo, a menudo con 和 (爸爸和妈妈). Modificador y núcleo: lo que describe va siempre delante (中国朋友, 很冷). Verbo y objeto: el objeto va detrás del verbo (喝茶). Sujeto y predicado: quién hace algo o cómo es (我喝茶, 今天很冷). A diferencia del español, el modificador nunca va detrás: «un amigo chino» es 一个中国朋友.', '[{"zh":"爸爸和妈妈都在家。","pinyin":"Bàba hé māma dōu zài jiā.","es":"Papá y mamá están en casa."},{"zh":"他是我的中国朋友。","pinyin":"Tā shì wǒ de Zhōngguó péngyou.","es":"Es mi amigo chino."},{"zh":"我喝茶。","pinyin":"Wǒ hē chá.","es":"Bebo té."},{"zh":"今天很冷。","pinyin":"Jīntiān hěn lěng.","es":"Hoy hace mucho frío."}]'::jsonb, array['（1）联合短语', '（2）偏正短语', '（3）动宾短语', '（4）主谓短语']::text[], 25, array['和', '中国朋友', '喝茶', '很冷']::text[], '[{"wrong":"我有一个朋友中国。","right":"我有一个中国朋友。","why":"El modificador va delante del núcleo: «amigo chino» se dice 中国朋友, al revés que en español."}]'::jsonb, '[]'::jsonb),
