  (1, '7.2', '特殊表达法', '时间表示法', null, '时间表示法', null, null, '[]'::jsonb, array['（1）年、月、日、星期表示法', '（2）钟点表示法']::text[], 49, '{}'::text[], '[]'::jsonb, '[]'::jsonb),
  (2, '1.1', '语素', '后缀', null, '后缀', '前 / 后 / 里 / 外 / 上 / 下 + 面', '面 se pega a una palabra de posición y forma un sustantivo de lugar: 前面 «delante», 里面 «dentro», 上面 «encima». Funciona igual que 边 (前边, 里边) y casi siempre se pueden intercambiar. Como son sustantivos, pueden ir solos como sujeto (外面下雨了) o detrás de un nombre, sin 的: 桌子上面. Al revés que en español, primero va el objeto de referencia y después la posición: «encima de la mesa» es 桌子上面.', '[{"zh":"医院在商店前面。","pinyin":"Yīyuàn zài shāngdiàn qiánmiàn.","es":"El hospital está delante de la tienda."},{"zh":"学校后面有一个饭馆。","pinyin":"Xuéxiào hòumiàn yǒu yí gè fànguǎn.","es":"Detrás del colegio hay un restaurante."},{"zh":"书包里面有什么？","pinyin":"Shūbāo lǐmiàn yǒu shénme?","es":"¿Qué hay dentro de la mochila?"},{"zh":"外面下雨了。","pinyin":"Wàimiàn xià yǔ le.","es":"Fuera está lloviendo."},{"zh":"你的手机在桌子上面。","pinyin":"Nǐ de shǒujī zài zhuōzi shàngmiàn.","es":"Tu móvil está encima de la mesa."}]'::jsonb, array['面']::text[], 1, array['前面', '后面', '里面', '外面', '上面']::text[], '[{"wrong":"你的手机在上面桌子。","right":"你的手机在桌子上面。","why":"La posición va detrás del objeto de referencia, no delante como en «encima de la mesa»."}]'::jsonb, '[{"hsk_level":1,"code":"1.2"},{"hsk_level":1,"code":"2.1.1"}]'::jsonb),
  (2, '2.1.1', '词类', '名词', '方位名词', '方位名词', 'lugar + 左边 / 右边 · 往左 / 往右 + verbo', '左 «izquierda» y 右 «derecha» casi nunca van solos como lugar: se usan como 左边 y 右边. Siguen la misma regla que 上 o 里: primero el objeto de referencia y después la posición, 学校右边 «a la derecha del colegio». Para indicar una dirección se combinan con 往: 往右走 «gira a la derecha».', '[{"zh":"我家左边是一个超市。","pinyin":"Wǒ jiā zuǒbian shì yí gè chāoshì.","es":"A la izquierda de mi casa hay un supermercado."},{"zh":"医院在学校右边。","pinyin":"Yīyuàn zài xuéxiào yòubian.","es":"El hospital está a la derecha del colegio."},{"zh":"你往右走。","pinyin":"Nǐ wǎng yòu zǒu.","es":"Gira a la derecha."},{"zh":"坐在我左边的是我朋友。","pinyin":"Zuò zài wǒ zuǒbian de shì wǒ péngyou.","es":"Quien está sentado a mi izquierda es mi amigo."}]'::jsonb, array['左、右']::text[], 2, array['左', '右']::text[], '[{"wrong":"医院在右边学校。","right":"医院在学校右边。","why":"右边 va detrás del lugar de referencia; el orden de «a la derecha del colegio» se invierte."}]'::jsonb, '[{"hsk_level":1,"code":"2.1.1"}]'::jsonb),
  (2, '2.2.1', '词类', '动词', '动词重叠', '动词重叠', 'V + V · V + 一 + V · V + 了 + V · AB + AB', 'Repetir un verbo suaviza la acción: indica que dura poco, que se hace sin esfuerzo o que solo se intenta. Por eso sirve para pedir algo con cortesía (你看看) o proponer (我们休息休息吧). Con 了 en medio (想了想) cuenta una acción breve que ya se hizo. Los verbos de dos sílabas se repiten enteros, ABAB, nunca AABB. No encaja con una duración larga ni con verbos que no son acciones, como 是 o 有.', '[{"zh":"你看看这本书。","pinyin":"Nǐ kànkan zhè běn shū.","es":"Échale un vistazo a este libro."},{"zh":"晚上我看看书，也喝茶。","pinyin":"Wǎnshang wǒ kànkan shū, yě hē chá.","es":"Por la noche leo un rato y tomo té."},{"zh":"这个问题你再想一想。","pinyin":"Zhège wèntí nǐ zài xiǎng yi xiǎng.","es":"Piensa un poco más en esta pregunta."},{"zh":"他想了想，说：“好吧。”","pinyin":"Tā xiǎng le xiǎng, shuō: “Hǎo ba.”","es":"Lo pensó un momento y dijo: «Vale»."},{"zh":"我们休息休息吧。","pinyin":"Wǒmen xiūxi xiūxi ba.","es":"Descansemos un poco."}]'::jsonb, array['AA、A一A、A了A、ABAB']::text[], 3, array['看看', '想一想', '想了想', '休息休息']::text[], '[{"wrong":"我看看了三个小时书。","right":"我看了三个小时书。","why":"La repetición indica que la acción es breve; no encaja con una duración larga."},{"wrong":"我们休休息息吧。","right":"我们休息休息吧。","why":"Los verbos de dos sílabas se repiten como bloque (ABAB); AABB es la forma de los adjetivos."}]'::jsonb, '[{"hsk_level":2,"code":"2.4.1"}]'::jsonb),
  (2, '2.2.2', '词类', '动词', '能愿动词', '能愿动词', '可能 + verbo / frase · 不可能', '可能 expresa probabilidad: algo que quizá pase o quizá sea cierto, como «puede que» o «a lo mejor». Va delante del verbo o al principio de la frase (可能他不来了). No sirve para la capacidad ni para el permiso: «sé / puedo hablar chino» se dice con 会 o 能, y para pedir permiso se usa 可以. 不可能 significa «es imposible».', '[{"zh":"明天可能下雨。","pinyin":"Míngtiān kěnéng xià yǔ.","es":"Puede que mañana llueva."},{"zh":"他可能不来了。","pinyin":"Tā kěnéng bù lái le.","es":"A lo mejor ya no viene."},{"zh":"可能他已经回家了。","pinyin":"Kěnéng tā yǐjīng huí jiā le.","es":"Quizá ya ha vuelto a casa."},{"zh":"这不可能！","pinyin":"Zhè bù kěnéng!","es":"¡Eso es imposible!"}]'::jsonb, array['可能']::text[], 4, array['可能']::text[], '[{"wrong":"我可能说汉语。","right":"我会说汉语。","why":"可能 no es el «poder» de saber hacer algo; para eso se usa 会. 可能 solo dice que algo es probable."}]'::jsonb, '[{"hsk_level":1,"code":"2.2.1"}]'::jsonb),
  (2, '2.2.3', '词类', '动词', '离合词', '离合词', 'V + (了 / 过 / duración / 的…) + O: 帮我的忙 · 游了一个小时泳', 'Estos verbos son un verbo y su objeto pegados, así que se pueden separar: 了, 过, una duración o un posesivo van en medio. Por eso no admiten otro objeto detrás: «ayudarte» no es «帮忙你», sino 帮你的忙 o simplemente 帮你. La duración también se mete en medio: 跑了半个小时步. Sin separar, se usan como un verbo sin objeto: 她喜欢跳舞.', '[{"zh":"你能帮我一个忙吗？","pinyin":"Nǐ néng bāng wǒ yí gè máng ma?","es":"¿Me puedes hacer un favor?"},{"zh":"我昨天游了一个小时泳。","pinyin":"Wǒ zuótiān yóu le yí gè xiǎoshí yǒng.","es":"Ayer nadé una hora."},{"zh":"她很喜欢跳舞。","pinyin":"Tā hěn xǐhuan tiàowǔ.","es":"Le encanta bailar."},{"zh":"我每天早上跑半个小时步。","pinyin":"Wǒ měi tiān zǎoshang pǎo bàn gè xiǎoshí bù.","es":"Cada mañana corro media hora."}]'::jsonb, array['帮忙、游泳、跳舞、跑步']::text[], 5, array['帮', '游', '跳舞', '跑']::text[], '[{"wrong":"你能帮忙我吗？","right":"你能帮我的忙吗？","why":"帮忙 ya lleva su objeto (忙): la persona va en medio, 帮我的忙, o se usa solo 帮: 帮我."},{"wrong":"我游泳了一个小时。","right":"我游了一个小时泳。","why":"La duración se mete entre el verbo y su objeto interno, no detrás del verbo entero."}]'::jsonb, '[{"hsk_level":1,"code":"2.2.2"}]'::jsonb),
  (2, '2.3.1', '词类', '代词', '疑问代词', '疑问代词', 'Sujeto + 为什么 + verbo？', '为什么 pregunta por la causa, como «¿por qué?». Va detrás del sujeto y delante del verbo, no al final de la frase: 你为什么不去？ La respuesta suele empezar con 因为. Como la frase ya es una pregunta, no se añade 吗.', '[{"zh":"你为什么不去？","pinyin":"Nǐ wèishénme bú qù?","es":"¿Por qué no vas?"},{"zh":"他为什么没来上课？","pinyin":"Tā wèishénme méi lái shàngkè?","es":"¿Por qué no vino a clase?"},{"zh":"为什么你每天都这么累？","pinyin":"Wèishénme nǐ měi tiān dōu zhème lèi?","es":"¿Por qué estás tan cansado todos los días?"},{"zh":"“你为什么学汉语？”“因为我喜欢中国。”","pinyin":"“Nǐ wèishénme xué Hànyǔ?” “Yīnwèi wǒ xǐhuan Zhōngguó.”","es":"—¿Por qué estudias chino? —Porque me gusta China."}]'::jsonb, array['为什么']::text[], 6, array['为什么']::text[], '[{"wrong":"你不去为什么？","right":"你为什么不去？","why":"为什么 va delante del verbo; no se deja al final como en «no vas, ¿por qué?»."},{"wrong":"你为什么不去吗？","right":"你为什么不去？","why":"Con 为什么 la frase ya es una pregunta; 吗 sobra."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.1"}]'::jsonb),
  (2, '2.3.2', '词类', '代词', '人称代词', '人称代词', 'Pronombre + 自己 + verbo · 自己的 + nombre', '自己 significa «uno mismo» y no cambia con la persona. Detrás del sujeto subraya que es él y no otro quien hace la acción, o que la hace sin ayuda: 我自己去, 他自己做饭. También puede ser objeto (只想自己) o posesivo con 的 (自己的房间). Va siempre delante del verbo cuando significa «yo mismo», nunca al final.', '[{"zh":"我自己去吧。","pinyin":"Wǒ zìjǐ qù ba.","es":"Ya voy yo."},{"zh":"他每天自己做饭。","pinyin":"Tā měi tiān zìjǐ zuò fàn.","es":"Se hace la comida él solo todos los días."},{"zh":"这是我自己的房间。","pinyin":"Zhè shì wǒ zìjǐ de fángjiān.","es":"Esta es mi propia habitación."},{"zh":"你不能只想自己。","pinyin":"Nǐ bù néng zhǐ xiǎng zìjǐ.","es":"No puedes pensar solo en ti."}]'::jsonb, array['自己']::text[], 7, array['自己']::text[], '[{"wrong":"我去自己。","right":"我自己去。","why":"Para «voy yo mismo», 自己 va pegado al sujeto y delante del verbo, no al final como en español."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.2"}]'::jsonb),
  (2, '2.3.3', '词类', '代词', '指示代词', '指示代词', '这么 / 那么 + adjetivo · 这样 / 那样 + verbo · 每 + clasificador + nombre (+ 都)', '这么 y 那么 van delante de un adjetivo y equivalen a «tan»: 这么贵. 这样 y 那样 significan «así, de esta manera»: delante de un verbo (这样写) o, con 的, delante de un nombre (那样的人). Con 这 se señala lo cercano o lo que se acaba de decir; con 那, lo lejano. 每 «cada» va con un clasificador (每个人, 每天) y casi siempre se refuerza con 都 delante del verbo.', '[{"zh":"这件衣服这么贵！","pinyin":"Zhè jiàn yīfu zhème guì!","es":"¡Esta ropa es tan cara!"},{"zh":"你不要那么说。","pinyin":"Nǐ búyào nàme shuō.","es":"No lo digas así."},{"zh":"这个字要这样写。","pinyin":"Zhège zì yào zhèyàng xiě.","es":"Este carácter se escribe así."},{"zh":"我不喜欢那样的人。","pinyin":"Wǒ bù xǐhuan nàyàng de rén.","es":"No me gusta la gente así."},{"zh":"他每天都跑步。","pinyin":"Tā měi tiān dōu pǎobù.","es":"Corre todos los días."}]'::jsonb, array['那么、那样、这么、这样、每']::text[], 8, array['这么', '那么', '这样', '那样', '每']::text[], '[{"wrong":"这件衣服很这么贵。","right":"这件衣服这么贵。","why":"这么 ya hace de «tan»; no se combina con 很."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.3"}]'::jsonb),
  (2, '2.4.1', '词类', '形容词', '形容词重叠', '形容词重叠', 'AA(的 / 地) · AABB(的 / 地)', 'Repetir un adjetivo lo hace más vivo y expresivo, como «bien grande» o un diminutivo en español. Los de una sílaba se repiten AA (大大的, 慢慢地) y los de dos, AABB (高高兴兴). La forma repetida ya lleva la intensidad, así que no admite 很 ni 非常 delante. Suele terminar en 的 cuando describe un nombre y en 地 cuando acompaña a un verbo.', '[{"zh":"她的眼睛大大的。","pinyin":"Tā de yǎnjing dàdà de.","es":"Tiene los ojos bien grandes."},{"zh":"你慢慢地说。","pinyin":"Nǐ mànmàn de shuō.","es":"Habla despacito."},{"zh":"孩子高高兴兴地回家了。","pinyin":"Háizi gāogāoxìngxìng de huí jiā le.","es":"El niño volvió a casa muy contento."},{"zh":"她今天穿得漂漂亮亮的。","pinyin":"Tā jīntiān chuān de piàopiaoliàngliàng de.","es":"Hoy va muy arreglada."}]'::jsonb, array['AA、AABB']::text[], 9, array['大大', '慢慢', '高高兴兴', '漂漂亮亮']::text[], '[{"wrong":"她的眼睛很大大的。","right":"她的眼睛大大的。","why":"La repetición ya intensifica; añadir 很 sobra."},{"wrong":"孩子高兴高兴地回家了。","right":"孩子高高兴兴地回家了。","why":"Los adjetivos de dos sílabas se repiten AABB; ABAB es la forma de los verbos (休息休息)."}]'::jsonb, '[{"hsk_level":2,"code":"2.2.1"}]'::jsonb),
  (2, '2.5', '词类', '数词', null, '数词', '一万 / 十万 · 好多 + nombre · número + 多 (+ clasificador)', '万 es la unidad de diez mil: el chino agrupa de diez mil en diez mil, así que cien mil es 十万. 好多 significa «muchísimos» y va delante del nombre, como 很多 pero más coloquial. 多 detrás de un número añade «y pico»: con decenas va delante del clasificador (二十多岁, «veintitantos años»); con unidades, detrás (一个多小时, «más de una hora»).', '[{"zh":"我们学校有一万个学生。","pinyin":"Wǒmen xuéxiào yǒu yíwàn gè xuésheng.","es":"Nuestro colegio tiene diez mil estudiantes."},{"zh":"商店里有好多人。","pinyin":"Shāngdiàn li yǒu hǎoduō rén.","es":"En la tienda hay muchísima gente."},{"zh":"他二十多岁。","pinyin":"Tā èrshí duō suì.","es":"Tiene veintitantos años."},{"zh":"我等了一个多小时。","pinyin":"Wǒ děng le yí gè duō xiǎoshí.","es":"Esperé más de una hora."},{"zh":"这个手机三千多块钱。","pinyin":"Zhège shǒujī sānqiān duō kuài qián.","es":"Este móvil cuesta tres mil y pico yuanes."}]'::jsonb, array['万、好多、多']::text[], 10, array['万', '好多', '多']::text[], '[{"wrong":"我们学校有十千个学生。","right":"我们学校有一万个学生。","why":"«十千» no existe: a partir de diez mil se cuenta con 万."},{"wrong":"我等了一个小时多。","right":"我等了一个多小时。","why":"Con unidades, 多 va entre el clasificador y el nombre: 一个多小时, no al final."}]'::jsonb, '[{"hsk_level":1,"code":"2.4"}]'::jsonb),
  (2, '2.6.1', '词类', '量词', '名量词', '名量词', 'número / 这 / 那 + 条 / 位 / 间 / 名 / 包 + nombre', 'Cada clasificador va con un tipo de nombre. 条 cuenta cosas largas y estrechas: calles, ríos, peces, pantalones. 位 cuenta personas con respeto (这位老师) y es más cortés que 个. 间 cuenta habitaciones y aulas, y 名 cuenta personas dentro de un grupo o una lista, como los alumnos de una clase. 包 es un clasificador prestado: «paquete», para lo que viene envasado (一包茶).', '[{"zh":"这条路很长。","pinyin":"Zhè tiáo lù hěn cháng.","es":"Esta calle es muy larga."},{"zh":"这位是我们的老师。","pinyin":"Zhè wèi shì wǒmen de lǎoshī.","es":"Este es nuestro profesor."},{"zh":"这间教室很大。","pinyin":"Zhè jiān jiàoshì hěn dà.","es":"Esta aula es muy grande."},{"zh":"我们班有三十名学生。","pinyin":"Wǒmen bān yǒu sānshí míng xuésheng.","es":"Nuestra clase tiene treinta alumnos."},{"zh":"我买了一包茶和两条鱼。","pinyin":"Wǒ mǎi le yì bāo chá hé liǎng tiáo yú.","es":"Compré un paquete de té y dos peces."}]'::jsonb, array['（1）专用名量词：条、位、间、名', '（2）借用名量词：包']::text[], 11, array['条', '位', '间', '名', '包']::text[], '[{"wrong":"这个路很长。","right":"这条路很长。","why":"Las cosas largas y estrechas se cuentan con 条; 个 es el comodín para lo que no tiene clasificador propio."}]'::jsonb, '[{"hsk_level":1,"code":"2.5.1"}]'::jsonb),
  (2, '2.6.2', '词类', '量词', '动量词', '动量词', 'verbo + (了 / 过) + número + 次 (+ objeto)', '次 cuenta las veces que ocurre una acción, como «vez». Va detrás del verbo y de 了 o 过: 去过两次. Un objeto común suele ir detrás de 次 (上两次课); un lugar o una persona pueden ir antes (去过中国两次). Para preguntar se usa 几次. Al contrario que en español, las veces nunca van delante del verbo.', '[{"zh":"我去过中国两次。","pinyin":"Wǒ qùguo Zhōngguó liǎng cì.","es":"He estado en China dos veces."},{"zh":"这个电影我看了三次。","pinyin":"Zhège diànyǐng wǒ kàn le sān cì.","es":"Esta película la he visto tres veces."},{"zh":"你来过几次？","pinyin":"Nǐ láiguo jǐ cì?","es":"¿Cuántas veces has venido?"},{"zh":"我们一个星期上两次课。","pinyin":"Wǒmen yí gè xīngqī shàng liǎng cì kè.","es":"Tenemos clase dos veces por semana."}]'::jsonb, array['次']::text[], 12, array['次']::text[], '[{"wrong":"我两次去过中国。","right":"我去过中国两次。","why":"Las veces van detrás del verbo; delante, como en «dos veces he ido», no funciona."}]'::jsonb, '[{"hsk_level":1,"code":"4.6.1"}]'::jsonb),
  (2, '2.7.1', '词类', '副词', '程度副词', '程度副词', '最 + adjetivo / verbo · 好 + adjetivo (+ 啊) · 多 + adjetivo (+ 啊)', '最 forma el superlativo, «el más»: 最高, 最喜欢. 好 delante de un adjetivo intensifica con emoción, como «qué» o «muy»: 好冷啊！ 多 sirve para exclamar (多漂亮啊！) y para preguntar por una medida: 多大 «qué edad, qué tamaño». Para un «muy» neutro, sin exclamación, se sigue usando 很. El ámbito del superlativo va delante: 我们班最高的.', '[{"zh":"你最喜欢吃什么？","pinyin":"Nǐ zuì xǐhuan chī shénme?","es":"¿Qué es lo que más te gusta comer?"},{"zh":"他是我们班最高的。","pinyin":"Tā shì wǒmen bān zuì gāo de.","es":"Es el más alto de nuestra clase."},{"zh":"今天好冷啊！","pinyin":"Jīntiān hǎo lěng a!","es":"¡Qué frío hace hoy!"},{"zh":"这里多漂亮啊！","pinyin":"Zhèlǐ duō piàoliang a!","es":"¡Qué bonito es esto!"},{"zh":"你今年多大？","pinyin":"Nǐ jīnnián duō dà?","es":"¿Cuántos años tienes?"}]'::jsonb, array['多、好、最']::text[], 13, array['最', '好', '多']::text[], '[{"wrong":"他是最高在我们班。","right":"他是我们班最高的。","why":"El ámbito («de la clase») va delante de 最; no se añade un «en» con 在 al final."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.1"}]'::jsonb),
  (2, '2.7.2', '词类', '副词', '范围副词', '范围副词', 'Sujeto + (和 / 跟 + persona) + 一起 + verbo', '一起 significa «juntos» y va delante del verbo, nunca al final como en «vamos juntos». La persona con la que se hace algo se presenta antes con 和 o 跟: 我和朋友一起去. Para proponer un plan se combina con 吧: 我们一起吃饭吧.', '[{"zh":"我们一起去吧。","pinyin":"Wǒmen yìqǐ qù ba.","es":"Vamos juntos."},{"zh":"我和朋友一起吃饭。","pinyin":"Wǒ hé péngyou yìqǐ chī fàn.","es":"Como con un amigo."},{"zh":"他们每天一起上学。","pinyin":"Tāmen měi tiān yìqǐ shàngxué.","es":"Van juntos al colegio todos los días."},{"zh":"你跟我一起走吗？","pinyin":"Nǐ gēn wǒ yìqǐ zǒu ma?","es":"¿Te vienes conmigo?"}]'::jsonb, array['一起']::text[], 14, array['一起']::text[], '[{"wrong":"我们去一起吧。","right":"我们一起去吧。","why":"一起 va delante del verbo, no detrás como en «vamos juntos»."}]'::jsonb, '[{"hsk_level":1,"code":"2.7.2"}]'::jsonb),
  (2, '2.7.3', '词类', '副词', '时间副词', '时间副词', '已经 + V + 了 · 还 + V · 有时候 + V · 快(要) + V + 了 · 正 + V (+ 呢)', '已经 «ya» marca algo terminado y casi siempre lleva 了: 他已经走了. 还 es «todavía»: la situación sigue igual (他还在睡觉). 有时候, o 有时, es «a veces». 快 y 快要 anuncian que algo va a pasar enseguida y exigen 了 al final: 快下雨了. 正 dice que la acción está en marcha justo en ese momento: 我正吃饭呢.', '[{"zh":"他已经走了。","pinyin":"Tā yǐjīng zǒu le.","es":"Ya se ha ido."},{"zh":"十点了，他还在睡觉。","pinyin":"Shí diǎn le, tā hái zài shuìjiào.","es":"Son las diez y todavía está durmiendo."},{"zh":"我有时候坐地铁上班。","pinyin":"Wǒ yǒushíhou zuò dìtiě shàngbān.","es":"A veces voy al trabajo en metro."},{"zh":"快下雨了，我们回家吧。","pinyin":"Kuài xià yǔ le, wǒmen huí jiā ba.","es":"Va a llover, volvamos a casa."},{"zh":"他来的时候，我正吃饭呢。","pinyin":"Tā lái de shíhou, wǒ zhèng chī fàn ne.","es":"Cuando llegó, yo estaba comiendo."}]'::jsonb, array['还2、已经、有时（候）、快、快要、正']::text[], 15, array['已经', '还', '有时', '快', '正']::text[], '[{"wrong":"快要下雨。","right":"快要下雨了。","why":"快 y 快要 necesitan 了 al final; sin él la frase queda a medias."},{"wrong":"我已经吃饭。","right":"我已经吃饭了。","why":"已经 presenta algo ya terminado y pide 了."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.3"},{"hsk_level":1,"code":"2.6.5"}]'::jsonb),
  (2, '2.7.4', '词类', '副词', '频率副词', '频率副词', 'Sujeto + 经常 / 常 + verbo', '经常 y 常 significan «a menudo» y van delante del verbo, detrás del sujeto. 常 es más breve y algo más escrito; en la conversación se oye sobre todo 经常. No se colocan al final de la frase como en «voy mucho». Para negarlo basta con poner 不 delante: 不经常.', '[{"zh":"我经常去那个饭馆。","pinyin":"Wǒ jīngcháng qù nàge fànguǎn.","es":"Voy a menudo a ese restaurante."},{"zh":"他经常工作到很晚。","pinyin":"Tā jīngcháng gōngzuò dào hěn wǎn.","es":"A menudo trabaja hasta muy tarde."},{"zh":"你经常运动吗？","pinyin":"Nǐ jīngcháng yùndòng ma?","es":"¿Haces deporte a menudo?"},{"zh":"我不经常看电视。","pinyin":"Wǒ bù jīngcháng kàn diànshì.","es":"No veo mucho la tele."}]'::jsonb, array['常、经常']::text[], 16, array['经常']::text[], '[{"wrong":"我去那个饭馆经常。","right":"我经常去那个饭馆。","why":"经常 va delante del verbo, no al final como en «voy ahí a menudo»."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.4"}]'::jsonb),
  (2, '2.7.5', '词类', '副词', '否定副词', '否定副词', '(你) + 别 + verbo (+ 了)', '别 pide a alguien que no haga algo: «no…». Es más directo y coloquial que 不要 y va delante del verbo. Con 了 al final pide que se deje de hacer algo que ya está pasando: 别说了 «deja de hablar». No sirve para negar hechos: «no fui» es 我没去.', '[{"zh":"别走！","pinyin":"Bié zǒu!","es":"¡No te vayas!"},{"zh":"别说了，我知道了。","pinyin":"Bié shuō le, wǒ zhīdào le.","es":"Deja de hablar, ya lo sé."},{"zh":"外面下雨，别出去了。","pinyin":"Wàimiàn xià yǔ, bié chūqu le.","es":"Fuera llueve, no salgas."},{"zh":"你别喝太多。","pinyin":"Nǐ bié hē tài duō.","es":"No bebas demasiado."}]'::jsonb, array['别']::text[], 17, array['别']::text[], '[{"wrong":"我昨天别去学校。","right":"我昨天没去学校。","why":"别 solo pide que alguien no haga algo; para negar lo que pasó se usa 没."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.6"},{"hsk_level":2,"code":"6.2.2"}]'::jsonb),
  (2, '2.7.6', '词类', '副词', '关联副词', '关联副词', 'V1 (+ 了…) + 再 + V2 · V1 + 了… + 就 + V2', 'Los dos enlazan dos acciones: la segunda ocurre después de la primera y van delante del segundo verbo. 再 mira hacia lo que aún no ha pasado, a menudo para pedir que se espere: 吃了饭再走 «come y después te vas». 就 subraya que la segunda acción llega enseguida y vale también para lo que ya ocurrió: 他下了课就回家了.', '[{"zh":"我们吃了饭再走吧。","pinyin":"Wǒmen chī le fàn zài zǒu ba.","es":"Comamos y después nos vamos."},{"zh":"你休息一下，明天再说。","pinyin":"Nǐ xiūxi yíxià, míngtiān zài shuō.","es":"Descansa un poco; mañana lo hablamos."},{"zh":"他下了课就回家了。","pinyin":"Tā xià le kè jiù huí jiā le.","es":"Al salir de clase se fue directo a casa."},{"zh":"我到了就给你打电话。","pinyin":"Wǒ dào le jiù gěi nǐ dǎ diànhuà.","es":"En cuanto llegue te llamo."}]'::jsonb, array['再2、就1']::text[], 18, array['再', '就']::text[], '[{"wrong":"他下了课再回家了。","right":"他下了课就回家了。","why":"Para lo que ya pasó se usa 就; 再 solo mira hacia lo que todavía no ha ocurrido."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.4"}]'::jsonb),
  (2, '2.7.7', '词类', '副词', '语气副词', '语气副词', '都 + tiempo / cantidad + 了 · 就 + verbo / 是 · 还是 + verbo (+ 吧)', 'Estos adverbios añaden la opinión de quien habla. 都…了 subraya que algo es más tarde o más de lo esperado: 都十点了 «¡si ya son las diez!». 就 insiste en que es exactamente eso: 这就是我的家 «esta es precisamente mi casa». 还是 recomienda la opción que, pensándolo bien, parece mejor: 你还是去吧 «mejor ve».', '[{"zh":"都十点了，你怎么还不起床？","pinyin":"Dōu shí diǎn le, nǐ zěnme hái bù qǐchuáng?","es":"¡Si ya son las diez! ¿Cómo es que no te levantas?"},{"zh":"这就是我的家。","pinyin":"Zhè jiù shì wǒ de jiā.","es":"Esta es precisamente mi casa."},{"zh":"我就要这个。","pinyin":"Wǒ jiù yào zhège.","es":"Quiero justo este."},{"zh":"外面很冷，你还是别出去了。","pinyin":"Wàimiàn hěn lěng, nǐ háishi bié chūqu le.","es":"Fuera hace mucho frío; mejor no salgas."},{"zh":"我们还是坐出租车吧。","pinyin":"Wǒmen háishi zuò chūzūchē ba.","es":"Mejor vamos en taxi."}]'::jsonb, array['都2、就2、还是1']::text[], 19, array['都', '就', '还是']::text[], '[{"wrong":"都十点，你怎么还不起床？","right":"都十点了，你怎么还不起床？","why":"都 con el sentido de «ya» necesita 了 al final."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.2"},{"hsk_level":2,"code":"4.1"}]'::jsonb),
  (2, '2.8.1', '词类', '介词', '引出时间、处所', '引出时间、处所', '从 + tiempo / lugar (+ 到 + tiempo / lugar) + verbo', '从 marca el punto de partida, en el tiempo o en el espacio: «desde», «de». Se combina a menudo con 到 para el final: 从九点到十二点. Todo el grupo va delante del verbo, no detrás: «vengo de China» es 我从中国来.', '[{"zh":"我从中国来。","pinyin":"Wǒ cóng Zhōngguó lái.","es":"Vengo de China."},{"zh":"我们从九点到十二点上课。","pinyin":"Wǒmen cóng jiǔ diǎn dào shí’èr diǎn shàngkè.","es":"Tenemos clase de nueve a doce."},{"zh":"他从明天开始工作。","pinyin":"Tā cóng míngtiān kāishǐ gōngzuò.","es":"Empieza a trabajar a partir de mañana."},{"zh":"从我家到学校很近。","pinyin":"Cóng wǒ jiā dào xuéxiào hěn jìn.","es":"De mi casa al colegio hay muy poco."}]'::jsonb, array['从1']::text[], 20, array['从']::text[], '[{"wrong":"我来从中国。","right":"我从中国来。","why":"El grupo con 从 va delante del verbo; no se copia el orden de «vengo de China»."}]'::jsonb, '[{"hsk_level":1,"code":"2.7.1"}]'::jsonb),
  (2, '2.8.2', '词类', '介词', '引出方向、路径', '引出方向、路径', '往 + dirección + verbo · 从 + lugar de paso + verbo', '往 indica hacia dónde va el movimiento: 往前走 «sigue recto», 往左走 «gira a la izquierda». 从, además del punto de partida, marca el sitio por donde se pasa: 从这儿走 «ve por aquí», 从门口进来 «entra por la puerta». Los dos grupos van delante del verbo, nunca detrás.', '[{"zh":"你往前走，医院就在右边。","pinyin":"Nǐ wǎng qián zǒu, yīyuàn jiù zài yòubian.","es":"Sigue recto y el hospital está a la derecha."},{"zh":"往左走是车站。","pinyin":"Wǎng zuǒ zǒu shì chēzhàn.","es":"Si giras a la izquierda está la estación."},{"zh":"我们从这儿走吧。","pinyin":"Wǒmen cóng zhèr zǒu ba.","es":"Vamos por aquí."},{"zh":"他从门口进来了。","pinyin":"Tā cóng ménkǒu jìnlai le.","es":"Entró por la puerta."}]'::jsonb, array['往', '从2']::text[], 21, array['往', '从']::text[], '[{"wrong":"你走往前。","right":"你往前走。","why":"往 y la dirección van delante del verbo, no detrás como en «camina hacia delante»."}]'::jsonb, '[{"hsk_level":2,"code":"2.8.1"}]'::jsonb),
  (2, '2.8.3', '词类', '介词', '引出对象', '引出对象', '给 + persona + verbo · 跟 + persona + verbo · A + 比 + B + adjetivo', 'Las tres presentan a la otra persona o cosa de la acción y van delante del verbo. 给 dice a quién va dirigida o para quién es: 给妈妈打电话 «llamar a mamá». 跟 es «con» o «a» en las acciones de dos: 跟朋友说话, 跟我来. 比 introduce con qué se compara: 他比我高; el adjetivo va al final y sin 很.', '[{"zh":"我晚上给你打电话。","pinyin":"Wǒ wǎnshang gěi nǐ dǎ diànhuà.","es":"Te llamo esta noche."},{"zh":"妈妈给我买了一件衣服。","pinyin":"Māma gěi wǒ mǎi le yí jiàn yīfu.","es":"Mamá me compró ropa."},{"zh":"我跟你说一件事。","pinyin":"Wǒ gēn nǐ shuō yí jiàn shì.","es":"Te voy a contar una cosa."},{"zh":"他比我高。","pinyin":"Tā bǐ wǒ gāo.","es":"Es más alto que yo."}]'::jsonb, array['给', '比', '跟1']::text[], 22, array['给', '跟', '比']::text[], '[{"wrong":"我说你一件事。","right":"我跟你说一件事。","why":"说 no lleva a la persona como objeto: «decirle algo a alguien» pide 跟 delante, 跟你说."},{"wrong":"他比我很高。","right":"他比我高。","why":"En una comparación con 比 el adjetivo va solo, sin 很."}]'::jsonb, '[{"hsk_level":1,"code":"2.7.2"},{"hsk_level":2,"code":"6.3.4"}]'::jsonb),
  (2, '2.8.4', '词类', '介词', '引出原因', '引出原因', 'Sujeto + 因为 + causa + predicado', '因为 también puede ir dentro de una sola frase, delante del verbo y con la causa justo detrás: 他因为生病没来. Así se da el motivo sin partir la frase en dos. La causa puede ser un nombre (因为这件事) o una frase corta. Si va detrás del verbo, necesita una pausa y forma otra frase: 他没来，因为他生病了.', '[{"zh":"他因为生病没来上课。","pinyin":"Tā yīnwèi shēngbìng méi lái shàngkè.","es":"No vino a clase porque estaba enfermo."},{"zh":"我因为这件事很不高兴。","pinyin":"Wǒ yīnwèi zhè jiàn shì hěn bù gāoxìng.","es":"Estoy muy disgustado por este asunto."},{"zh":"她因为工作很忙，没时间运动。","pinyin":"Tā yīnwèi gōngzuò hěn máng, méi shíjiān yùndòng.","es":"Como tiene mucho trabajo, no tiene tiempo para hacer deporte."},{"zh":"我们因为下雨没出去。","pinyin":"Wǒmen yīnwèi xià yǔ méi chūqu.","es":"No salimos por la lluvia."}]'::jsonb, array['因为1']::text[], 23, array['因为']::text[], '[{"wrong":"他没来上课因为生病。","right":"他因为生病没来上课。","why":"Sin pausa, 因为 y la causa van delante del verbo; detrás solo funcionan como otra frase: 他没来上课，因为他生病了."}]'::jsonb, '[{"hsk_level":2,"code":"6.4.3"}]'::jsonb),
  (2, '2.9.1', '词类', '连词', '连接词或短语', '连接词或短语', 'nombre / pronombre + 跟 + nombre / pronombre', '跟 puede unir dos nombres o pronombres, igual que 和: 我跟他 «él y yo». Solo une nombres, nunca dos verbos ni dos frases. Cuando después viene un verbo que vale para los dos, se suele poner 都 o 一起: 我跟他都是学生.', '[{"zh":"我跟他都是学生。","pinyin":"Wǒ gēn tā dōu shì xuésheng.","es":"Él y yo somos estudiantes."},{"zh":"爸爸跟妈妈都不在家。","pinyin":"Bàba gēn māma dōu bú zài jiā.","es":"Ni papá ni mamá están en casa."},{"zh":"我买了面包跟鸡蛋。","pinyin":"Wǒ mǎi le miànbāo gēn jīdàn.","es":"Compré pan y huevos."}]'::jsonb, array['跟2']::text[], 24, array['跟']::text[], '[{"wrong":"我吃了饭跟看了电视。","right":"我吃了饭，还看了电视。","why":"跟, como 和, solo une nombres; para encadenar dos acciones no sirve."}]'::jsonb, '[{"hsk_level":1,"code":"2.8.1"}]'::jsonb),
  (2, '2.9.2', '词类', '连词', '连接分句或者句子', '连接分句或者句子', '…，但是… · 虽然…，但是… · 那… · A 还是 B？ · 因为…，所以…', 'Estas palabras unen frases. 但是, o 但, introduce un contraste: «pero». 虽然 «aunque» va en la primera parte y se completa con 但是 en la segunda, cosa que en español sobraría. 那 al principio saca una conclusión de lo que acaba de decir el otro: «entonces». 还是 une dos opciones en una pregunta, «¿A o B?». 因为 presenta la causa y 所以 la consecuencia.', '[{"zh":"这件衣服很漂亮，但是太贵了。","pinyin":"Zhè jiàn yīfu hěn piàoliang, dànshì tài guì le.","es":"Esta ropa es muy bonita, pero demasiado cara."},{"zh":"虽然下雨了，但是他来了。","pinyin":"Suīrán xià yǔ le, dànshì tā lái le.","es":"Aunque llovía, vino."},{"zh":"“我不想去。”“那我们在家吧。”","pinyin":"“Wǒ bù xiǎng qù.” “Nà wǒmen zài jiā ba.”","es":"—No quiero ir. —Entonces quedémonos en casa."},{"zh":"你喝茶还是喝咖啡？","pinyin":"Nǐ hē chá háishi hē kāfēi?","es":"¿Tomas té o café?"},{"zh":"因为太累了，所以我没去。","pinyin":"Yīnwèi tài lèi le, suǒyǐ wǒ méi qù.","es":"Como estaba muy cansado, no fui."}]'::jsonb, array['但、但是、那、虽然、还是2、因为2、所以']::text[], 25, array['但', '虽然', '那', '还是', '所以']::text[], '[{"wrong":"虽然很贵，我买了。","right":"虽然很贵，但是我买了。","why":"虽然 pide su pareja 但是 en la segunda parte, aunque en español «aunque…, pero» sea incorrecto."},{"wrong":"你喝茶还是喝咖啡吗？","right":"你喝茶还是喝咖啡？","why":"Una pregunta con 还是 ya es pregunta; 吗 sobra."}]'::jsonb, '[{"hsk_level":2,"code":"6.4.1"},{"hsk_level":2,"code":"6.4.2"},{"hsk_level":2,"code":"6.4.3"}]'::jsonb),
  (2, '2.10.1', '词类', '助词', '结构助词', '结构助词', 'verbo + 得 + valoración · adjetivo + 地 + verbo', 'Los dos se pronuncian de y se distinguen por su sitio. 得 va detrás del verbo y presenta cómo sale la acción o hasta qué punto: 他说得很快. 地 va delante del verbo y convierte lo anterior en la manera de hacerlo, como el «-mente» español: 高兴地说. Si el verbo con 得 tiene objeto, se repite el verbo o se adelanta el objeto: 他汉语说得很好.', '[{"zh":"他说得很快。","pinyin":"Tā shuō de hěn kuài.","es":"Habla muy rápido."},{"zh":"你汉语说得真好！","pinyin":"Nǐ Hànyǔ shuō de zhēn hǎo!","es":"¡Qué bien hablas chino!"},{"zh":"她高兴地说：“谢谢！”","pinyin":"Tā gāoxìng de shuō: “Xièxie!”","es":"Dijo contenta: «¡Gracias!»."},{"zh":"我们慢慢地走吧。","pinyin":"Wǒmen mànmàn de zǒu ba.","es":"Vamos andando despacio."}]'::jsonb, array['得、地']::text[], 26, array['得', '地']::text[], '[{"wrong":"他说汉语得很好。","right":"他说汉语说得很好。","why":"得 va pegado al verbo; si hay objeto, se repite el verbo (说汉语说得) o se adelanta el objeto (汉语说得)."}]'::jsonb, '[{"hsk_level":1,"code":"2.9.1"},{"hsk_level":2,"code":"5.4.3"}]'::jsonb),
  (2, '2.10.2', '词类', '助词', '动态助词', '动态助词', 'verbo + 过 (experiencia) · verbo + 着 (estado que continúa)', '过 detrás del verbo cuenta una experiencia: algo que se ha hecho alguna vez, sin decir cuándo: 我去过中国. Se niega con 没…过. 着 indica que un estado se mantiene o que algo se hace a la vez que otra cosa: 门开着 «la puerta está abierta», 笑着说 «decir sonriendo». Los dos van pegados al verbo, antes del objeto.', '[{"zh":"我去过中国。","pinyin":"Wǒ qùguo Zhōngguó.","es":"He estado en China."},{"zh":"你吃过中国菜吗？","pinyin":"Nǐ chīguo Zhōngguó cài ma?","es":"¿Has probado la comida china?"},{"zh":"我没看过这个电影。","pinyin":"Wǒ méi kànguo zhège diànyǐng.","es":"No he visto esta película."},{"zh":"门开着。","pinyin":"Mén kāizhe.","es":"La puerta está abierta."},{"zh":"他笑着说：“没关系。”","pinyin":"Tā xiàozhe shuō: “Méi guānxi.”","es":"Dijo sonriendo: «No pasa nada»."}]'::jsonb, array['过', '着']::text[], 27, array['过', '着']::text[], '[{"wrong":"我不去过中国。","right":"我没去过中国。","why":"La experiencia con 过 se niega con 没, nunca con 不."}]'::jsonb, '[{"hsk_level":2,"code":"7.1.1"},{"hsk_level":2,"code":"7.1.2"}]'::jsonb),
  (2, '2.10.3', '词类', '助词', '语气助词', '语气助词', 'frase + 吧 / 呢 / 的 / 啊', 'Estas partículas finales dan el tono de la frase. 吧 detrás de una afirmación pide confirmación, como «¿verdad?»: 你是老师吧？ 呢 subraya un hecho que contradice lo esperado: 他还没来呢 «pues todavía no ha llegado». 的 al final da seguridad: 我会来的 «vendré, seguro». 啊 añade emoción o suaviza: 好啊！', '[{"zh":"你是老师吧？","pinyin":"Nǐ shì lǎoshī ba?","es":"Eres profesor, ¿verdad?"},{"zh":"他还没来呢。","pinyin":"Tā hái méi lái ne.","es":"Pues todavía no ha llegado."},{"zh":"我会来的。","pinyin":"Wǒ huì lái de.","es":"Vendré, seguro."},{"zh":"好啊，我们走吧。","pinyin":"Hǎo a, wǒmen zǒu ba.","es":"¡Vale, vámonos!"},{"zh":"今天天气真好啊！","pinyin":"Jīntiān tiānqì zhēn hǎo a!","es":"¡Qué buen tiempo hace hoy!"}]'::jsonb, array['呢4、吧2、的2、啊1']::text[], 28, array['吧', '呢', '的', '啊']::text[], '[{"wrong":"你是老师吧吗？","right":"你是老师吧？","why":"吧 ya convierte la frase en una pregunta de confirmación; no se junta con 吗."}]'::jsonb, '[{"hsk_level":1,"code":"2.9.3"}]'::jsonb),
  (2, '3.1.1', '短语', '结构类型', '基本结构类型', '基本结构类型', 'verbo + complemento de resultado / dirección: 看完, 听懂, 找到, 进来', 'El resultado de una acción se pega al verbo como un segundo elemento: 看完 «terminar de leer», 听懂 «entender lo que se oye», 找到 «encontrar». El primer verbo dice qué se hace y el segundo qué se consigue o hacia dónde va. Se niega con 没: 我没听懂. En español solemos usar otro verbo («encontrar» frente a «buscar»), por eso al principio se olvida el complemento.', '[{"zh":"我看完这本书了。","pinyin":"Wǒ kànwán zhè běn shū le.","es":"He terminado de leer este libro."},{"zh":"你说的我都听懂了。","pinyin":"Nǐ shuō de wǒ dōu tīngdǒng le.","es":"He entendido todo lo que has dicho."},{"zh":"我找到我的手机了。","pinyin":"Wǒ zhǎodào wǒ de shǒujī le.","es":"He encontrado mi móvil."},{"zh":"请进来！","pinyin":"Qǐng jìnlai!","es":"¡Pasa, por favor!"},{"zh":"我没听懂。","pinyin":"Wǒ méi tīngdǒng.","es":"No lo he entendido."}]'::jsonb, array['动补短语1']::text[], 29, array['完', '懂', '到', '进来']::text[], '[{"wrong":"我找我的手机了。","right":"我找到我的手机了。","why":"找 solo es «buscar»; para decir que lo has encontrado hace falta el resultado 到."},{"wrong":"我不听懂。","right":"我没听懂。","why":"Un verbo con resultado se niega con 没 cuando hablas de lo que pasó."}]'::jsonb, '[{"hsk_level":2,"code":"5.4.1"},{"hsk_level":2,"code":"5.4.2"}]'::jsonb),
  (2, '3.1.2', '短语', '结构类型', '其他结构类型', '其他结构类型', '… + 的 (sin nombre) · V1 + O1 + V2 + O2 · 请 / 让 + persona + verbo', 'Tres construcciones muy frecuentes. Con 的 al final se puede omitir el nombre cuando ya se sabe de qué se habla: 这本书是我的, 我要大的. Dos verbos seguidos, sin conjunción, encadenan acciones y el segundo suele ser la finalidad: 去商店买东西 «ir a la tienda a comprar». En 请朋友来, la persona es a la vez quien recibe el primer verbo y quien hace el segundo.', '[{"zh":"这本书是我的。","pinyin":"Zhè běn shū shì wǒ de.","es":"Este libro es mío."},{"zh":"我要大的，不要小的。","pinyin":"Wǒ yào dà de, bú yào xiǎo de.","es":"Quiero el grande, no el pequeño."},{"zh":"我去商店买东西。","pinyin":"Wǒ qù shāngdiàn mǎi dōngxi.","es":"Voy a la tienda a comprar."},{"zh":"他坐飞机去中国。","pinyin":"Tā zuò fēijī qù Zhōngguó.","es":"Va a China en avión."},{"zh":"我请朋友来我家吃饭。","pinyin":"Wǒ qǐng péngyou lái wǒ jiā chī fàn.","es":"Invito a unos amigos a comer a casa."}]'::jsonb, array['（1）“的”字短语', '（2）连谓短语', '（3）兼语短语']::text[], 30, array['的', '去商店买', '坐飞机去', '请']::text[], '[{"wrong":"我去买东西在商店。","right":"我去商店买东西。","why":"Las acciones van en orden: primero adónde vas y luego qué haces allí; el lugar no se deja al final."}]'::jsonb, '[{"hsk_level":1,"code":"3.1.2"},{"hsk_level":1,"code":"5.3.4"},{"hsk_level":2,"code":"6.3.6"}]'::jsonb),
  (2, '3.2.1', '短语', '功能类型', '名词性短语', '名词性短语', '这 / 那 + número + clasificador + (descripción + 的) + nombre', 'Un grupo nominal funciona como un nombre: puede ser sujeto u objeto. Todo lo que describe al nombre va delante, en orden fijo: demostrativo, número, clasificador, descripción y, al final, el nombre: 那两本新书. Las descripciones largas llevan 的 (很好的朋友); las cortas y fijas, no (中国菜). En español la descripción suele ir detrás del nombre; en chino nunca.', '[{"zh":"那两本新书是我的。","pinyin":"Nà liǎng běn xīn shū shì wǒ de.","es":"Esos dos libros nuevos son míos."},{"zh":"我的老师是中国人。","pinyin":"Wǒ de lǎoshī shì Zhōngguó rén.","es":"Mi profesor es chino."},{"zh":"他是我很好的朋友。","pinyin":"Tā shì wǒ hěn hǎo de péngyou.","es":"Es un muy buen amigo mío."},{"zh":"我喜欢吃中国菜。","pinyin":"Wǒ xǐhuan chī Zhōngguó cài.","es":"Me gusta la comida china."}]'::jsonb, null, 31, array['两本新书', '我的老师', '很好的朋友', '中国菜']::text[], '[{"wrong":"我有朋友很好。","right":"我有很好的朋友。","why":"La descripción va delante del nombre con 的; detrás, como en «amigos muy buenos», no funciona."}]'::jsonb, '[{"hsk_level":1,"code":"4.4"}]'::jsonb),
  (2, '3.2.2', '短语', '功能类型', '动词性短语', '动词性短语', '(adverbio) + verbo + objeto / complemento', 'Un grupo verbal es un verbo con lo que lo acompaña: adverbios delante (每天跑步) y objeto o complemento detrás (看书, 看完). Además de predicado, puede ser sujeto u objeto sin cambiar de forma, porque el chino no tiene infinitivo: 学汉语很有意思 «estudiar chino es interesante», 我喜欢看书 «me gusta leer». Si el predicado es un adjetivo, no se pone 是 en medio.', '[{"zh":"学汉语很有意思。","pinyin":"Xué Hànyǔ hěn yǒu yìsi.","es":"Estudiar chino es muy interesante."},{"zh":"我喜欢看书。","pinyin":"Wǒ xǐhuan kàn shū.","es":"Me gusta leer."},{"zh":"每天跑步对身体好。","pinyin":"Měi tiān pǎobù duì shēntǐ hǎo.","es":"Correr todos los días es bueno para la salud."},{"zh":"他不想打电话。","pinyin":"Tā bù xiǎng dǎ diànhuà.","es":"No quiere llamar por teléfono."}]'::jsonb, null, 32, array['学汉语', '看书', '跑步', '打电话']::text[], '[{"wrong":"学汉语是很有意思。","right":"学汉语很有意思。","why":"Cuando el predicado es un adjetivo no se pone 是: el grupo verbal va seguido directamente de 很 + adjetivo."}]'::jsonb, '[{"hsk_level":1,"code":"4.2"}]'::jsonb),
  (2, '3.2.3', '短语', '功能类型', '形容词性短语', '形容词性短语', '很 / 非常 / 不太 + adjetivo · 太 + adjetivo + 了', 'Un grupo adjetival es un adjetivo con un adverbio de grado: 很好, 非常贵, 不太好, 太大了. Hace de predicado sin 是 (这个很贵) y, con 的, describe a un nombre (很贵的衣服). 不太 suaviza la negación, «no muy». 太…了 dice que algo pasa de la medida, «demasiado».', '[{"zh":"这个菜非常好吃。","pinyin":"Zhège cài fēicháng hǎochī.","es":"Este plato está riquísimo."},{"zh":"这件衣服太大了。","pinyin":"Zhè jiàn yīfu tài dà le.","es":"Esta ropa es demasiado grande."},{"zh":"今天天气不太好。","pinyin":"Jīntiān tiānqì bú tài hǎo.","es":"Hoy no hace muy buen tiempo."},{"zh":"我买了一件很贵的衣服。","pinyin":"Wǒ mǎi le yí jiàn hěn guì de yīfu.","es":"Me compré una ropa muy cara."}]'::jsonb, null, 33, array['很', '非常', '太', '不太']::text[], '[{"wrong":"这个菜是很好吃。","right":"这个菜很好吃。","why":"El adjetivo hace de predicado por sí solo; el «es» español no se traduce con 是."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.1"},{"hsk_level":1,"code":"4.2"}]'::jsonb),
  (2, '3.3.1', '短语', '固定短语', '其他', '其他', 'A、B + 什么的', '什么的 cierra una lista de ejemplos, como «y cosas así» o «etcétera». Va detrás del último elemento, sin 和 delante, y es propio de la conversación. Puede cerrar una lista de cosas (面包、鸡蛋什么的) o de actividades (看书、看电影什么的).', '[{"zh":"我买了面包、鸡蛋什么的。","pinyin":"Wǒ mǎi le miànbāo, jīdàn shénmede.","es":"Compré pan, huevos y cosas así."},{"zh":"星期天我喜欢看书、看电影什么的。","pinyin":"Xīngqītiān wǒ xǐhuan kàn shū, kàn diànyǐng shénmede.","es":"Los domingos me gusta leer, ver películas y cosas así."},{"zh":"桌子上有手机、书什么的。","pinyin":"Zhuōzi shang yǒu shǒujī, shū shénmede.","es":"En la mesa hay un móvil, libros y esas cosas."}]'::jsonb, array['什么的']::text[], 34, array['什么的']::text[], '[{"wrong":"我买了面包、鸡蛋和什么的。","right":"我买了面包、鸡蛋什么的。","why":"什么的 ya cierra la lista; no se pone 和 delante como en «y cosas así»."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.1"}]'::jsonb),
  (2, '4.1', '固定格式', '', null, '', '还是 + V + 吧 · 要 / 快要 / 就要 + V + 了 · 都 + … + 了', 'Tres moldes fijos. 还是…吧 recomienda la mejor opción después de pensarlo: 还是回家吧 «mejor volvamos a casa». 要…了, 快要…了 y 就要…了 anuncian que algo va a pasar pronto; si se dice cuándo (明天, 下个星期), solo vale 就要. 都…了 subraya que ya es tarde o que ya es mucho: 都十二点了.', '[{"zh":"太晚了，我们还是回家吧。","pinyin":"Tài wǎn le, wǒmen háishi huí jiā ba.","es":"Es muy tarde; mejor volvamos a casa."},{"zh":"火车快要开了。","pinyin":"Huǒchē kuàiyào kāi le.","es":"El tren está a punto de salir."},{"zh":"明天就要考试了。","pinyin":"Míngtiān jiù yào kǎoshì le.","es":"Mañana ya es el examen."},{"zh":"都十二点了，快睡觉吧。","pinyin":"Dōu shí’èr diǎn le, kuài shuìjiào ba.","es":"Ya son las doce; vete a dormir."}]'::jsonb, array['还是……吧', '要/快要/就要……了', '都……了']::text[], 35, array['还是', '快要', '就要', '都']::text[], '[{"wrong":"明天快要考试了。","right":"明天就要考试了。","why":"Con un momento concreto (明天) se usa 就要; 快要 no admite una indicación de tiempo."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.3"},{"hsk_level":2,"code":"2.7.7"}]'::jsonb),
  (2, '5.1', '句子成分', '主语', null, '主语', 'Objeto (como sujeto) + verbo + resultado / 了', 'Lo que recibe la acción puede ir al principio, como sujeto, sin ninguna marca de pasiva: 饭做好了 «la comida está hecha». Se usa cuando importa la cosa y no quién lo hizo, porque ya se sabe o da igual. El verbo casi siempre lleva un resultado o 了. En español equivale a una pasiva refleja («se ha agotado») o a «está hecho».', '[{"zh":"饭做好了，快来吃吧。","pinyin":"Fàn zuòhǎo le, kuài lái chī ba.","es":"La comida está lista, venid a comer."},{"zh":"衣服洗好了吗？","pinyin":"Yīfu xǐhǎo le ma?","es":"¿Ya está lavada la ropa?"},{"zh":"那本书卖完了。","pinyin":"Nà běn shū màiwán le.","es":"Ese libro se ha agotado."},{"zh":"你的手机找到了。","pinyin":"Nǐ de shǒujī zhǎodào le.","es":"Tu móvil ha aparecido."}]'::jsonb, array['受事主语']::text[], 36, array['做好了', '洗好了', '卖完了', '找到了']::text[], '[{"wrong":"饭被做好了。","right":"饭做好了。","why":"No hace falta ninguna marca de pasiva: la cosa va delante y el verbo detrás. 被 se reserva para cuando hay que señalar quién lo hizo o algo salió mal."}]'::jsonb, '[{"hsk_level":1,"code":"4.1"}]'::jsonb),
  (2, '5.2', '句子成分', '谓语', null, '谓语', 'Sujeto + fecha / edad / precio / hora', 'Con fechas, horas, edades y precios, el predicado puede ser directamente un grupo nominal, sin verbo: 今天星期三, 他二十岁, 这个一百块. En español siempre hace falta un verbo («es», «tiene», «cuesta»); en chino no. Para negarlo, en cambio, sí aparece 是: 今天不是星期三.', '[{"zh":"今天星期三。","pinyin":"Jīntiān xīngqīsān.","es":"Hoy es miércoles."},{"zh":"我弟弟八岁。","pinyin":"Wǒ dìdi bā suì.","es":"Mi hermano pequeño tiene ocho años."},{"zh":"这件衣服一百块。","pinyin":"Zhè jiàn yīfu yìbǎi kuài.","es":"Esta ropa cuesta cien yuanes."},{"zh":"现在三点半。","pinyin":"Xiànzài sān diǎn bàn.","es":"Son las tres y media."},{"zh":"今天不是星期三。","pinyin":"Jīntiān bú shì xīngqīsān.","es":"Hoy no es miércoles."}]'::jsonb, array['名词性短语作谓语']::text[], 37, array['星期', '岁', '块', '点']::text[], '[{"wrong":"我弟弟有八岁。","right":"我弟弟八岁。","why":"La edad no se «tiene»: va directamente detrás del sujeto, sin 有."}]'::jsonb, '[{"hsk_level":1,"code":"4.2"},{"hsk_level":1,"code":"7.2"}]'::jsonb),
  (2, '5.3', '句子成分', '定语', null, '定语', '(sujeto +) verbo (+ …) + 的 + nombre', 'Una acción, o una frase entera con su sujeto, puede describir a un nombre si va delante con 的: 妈妈做的菜 «la comida que hace mamá», 来的人 «la gente que viene». Equivale a las oraciones con «que» del español, pero en orden inverso: primero la descripción y después el nombre, sin ningún «que».', '[{"zh":"妈妈做的菜很好吃。","pinyin":"Māma zuò de cài hěn hǎochī.","es":"La comida que hace mamá está muy rica."},{"zh":"这是我昨天买的书。","pinyin":"Zhè shì wǒ zuótiān mǎi de shū.","es":"Este es el libro que compré ayer."},{"zh":"今天来的人很多。","pinyin":"Jīntiān lái de rén hěn duō.","es":"Hoy ha venido mucha gente."},{"zh":"你说的话我都听懂了。","pinyin":"Nǐ shuō de huà wǒ dōu tīngdǒng le.","es":"He entendido todo lo que has dicho."}]'::jsonb, array['动词或动词性短语、主谓短语作定语']::text[], 38, array['做的菜', '买的书', '来的人', '说的话']::text[], '[{"wrong":"这是书我昨天买的。","right":"这是我昨天买的书。","why":"La descripción va delante del nombre; el «que» de «el libro que compré» no existe y el orden se invierte."}]'::jsonb, '[{"hsk_level":1,"code":"4.4"},{"hsk_level":2,"code":"3.2.1"}]'::jsonb),
  (2, '5.4.1', '句子成分', '补语', '结果补语1', '结果补语1', 'verbo + 完 / 好 / 懂 / 会 / 错', 'Estos complementos dicen cómo acaba la acción. 完 es «terminar» (吃完), 好 «dejar algo hecho y listo» (准备好), 懂 «entender» (听懂, 看懂), 会 «aprender a hacer algo» (学会) y 错 «hacerlo mal» (写错, 说错). Se niegan con 没 y suelen llevar 了 cuando ya ha pasado: 我没听懂, 我学会了.', '[{"zh":"我吃完了。","pinyin":"Wǒ chīwán le.","es":"Ya he terminado de comer."},{"zh":"我准备好了。","pinyin":"Wǒ zhǔnbèi hǎo le.","es":"Ya estoy listo."},{"zh":"这个字我写错了。","pinyin":"Zhège zì wǒ xiěcuò le.","es":"Este carácter lo he escrito mal."},{"zh":"你看懂了吗？","pinyin":"Nǐ kàndǒng le ma?","es":"¿Lo has entendido?"},{"zh":"我学会做中国菜了。","pinyin":"Wǒ xuéhuì zuò Zhōngguó cài le.","es":"He aprendido a hacer comida china."}]'::jsonb, array['动词+错/懂/好/会/完']::text[], 39, array['完', '好', '懂', '会', '错']::text[], '[{"wrong":"这个字我写得错了。","right":"这个字我写错了。","why":"El resultado 错 se pega directamente al verbo; 得 sirve para valorar cómo se hace, no para decir cómo acaba."}]'::jsonb, '[{"hsk_level":2,"code":"3.1.1"}]'::jsonb),
  (2, '5.4.2', '句子成分', '补语', '趋向补语1', '趋向补语1', 'verbo + 来 / 去 · verbo + 进 / 出 / 回 / 过 / 上 / 下 (+ 来 / 去)', 'Detrás del verbo se indica la dirección del movimiento. 来 es hacia quien habla y 去, alejándose de él: 进来 «entra aquí», 出去 «sal fuera». 进, 出, 回, 过, 上 y 下 dan la dirección concreta y se combinan con 来 o 去: 走过来, 跑出去. Si hay un lugar, va entre la dirección y 来 / 去: 回家去.', '[{"zh":"外面冷，快进来吧。","pinyin":"Wàimiàn lěng, kuài jìnlai ba.","es":"Fuera hace frío, entra."},{"zh":"他跑出去了。","pinyin":"Tā pǎo chūqu le.","es":"Salió corriendo."},{"zh":"妈妈什么时候回来？","pinyin":"Māma shénme shíhou huílai?","es":"¿Cuándo vuelve mamá?"},{"zh":"你走过来，我看看。","pinyin":"Nǐ zǒu guòlai, wǒ kànkan.","es":"Acércate, que te vea."}]'::jsonb, array['简单趋向补语的趋向意义用法：（1）动词+来/去', '（2）动词+上/下/进/出/过/回', '复合趋向补语的趋向意义用法：动词+出来/出去/过来/过去/回来/回去/进来/进去/起来/上来/上去/下来/下去']::text[], 40, array['进来', '出去', '回来', '过来']::text[], '[{"wrong":"他回去家了。","right":"他回家去了。","why":"El lugar va entre el verbo de dirección y 来 / 去: 回家去, no detrás de 去."}]'::jsonb, '[{"hsk_level":2,"code":"3.1.1"}]'::jsonb),
  (2, '5.4.3', '句子成分', '补语', '状态补语1', '状态补语1', 'verbo + 得 + (很 / 非常 / 不) + adjetivo', 'Para valorar cómo se hace una acción, el adjetivo va detrás del verbo con 得: 他跑得很快 «corre muy rápido». Describe lo habitual o lo que ya pasó; no sirve para dar órdenes. La negación va detrás de 得, sobre la valoración: 跑得不快. Si el verbo tiene objeto, se repite el verbo: 唱歌唱得很好.', '[{"zh":"他跑得很快。","pinyin":"Tā pǎo de hěn kuài.","es":"Corre muy rápido."},{"zh":"你今天来得很早。","pinyin":"Nǐ jīntiān lái de hěn zǎo.","es":"Hoy has venido muy pronto."},{"zh":"她唱歌唱得非常好。","pinyin":"Tā chàng gē chàng de fēicháng hǎo.","es":"Canta muy bien."},{"zh":"我昨天睡得不太好。","pinyin":"Wǒ zuótiān shuì de bú tài hǎo.","es":"Ayer no dormí muy bien."}]'::jsonb, array['动词+得+形容词性短语']::text[], 41, array['得']::text[], '[{"wrong":"他不跑得快。","right":"他跑得不快。","why":"La negación va detrás de 得, sobre la valoración; no delante del verbo."}]'::jsonb, '[{"hsk_level":2,"code":"2.10.1"}]'::jsonb),
  (2, '5.4.4', '句子成分', '补语', '数量补语2', '数量补语2', 'verbo + (了) + duración (+ objeto) · adjetivo + cantidad', 'La duración de una acción va detrás del verbo: 我学了两年汉语, 他睡了八个小时. Un objeto común se coloca detrás de la duración (两年汉语); un pronombre, delante (等了你半个小时). Detrás de un adjetivo, una cantidad expresa la diferencia: 他比我大两岁 «me lleva dos años». En español la duración puede abrir la frase; en chino no.', '[{"zh":"我学了两年汉语。","pinyin":"Wǒ xué le liǎng nián Hànyǔ.","es":"Estudié chino durante dos años."},{"zh":"他每天睡八个小时。","pinyin":"Tā měi tiān shuì bā gè xiǎoshí.","es":"Duerme ocho horas al día."},{"zh":"我等了你半个小时。","pinyin":"Wǒ děng le nǐ bàn gè xiǎoshí.","es":"Te he esperado media hora."},{"zh":"他比我大两岁。","pinyin":"Tā bǐ wǒ dà liǎng suì.","es":"Me lleva dos años."},{"zh":"这件比那件贵一百块。","pinyin":"Zhè jiàn bǐ nà jiàn guì yìbǎi kuài.","es":"Esta cuesta cien yuanes más que aquella."}]'::jsonb, array['（1）表示动作持续的时间', '（2）形容词+数量补语']::text[], 42, array['年', '小时', '岁', '块']::text[], '[{"wrong":"我两年学了汉语。","right":"我学了两年汉语。","why":"La duración va detrás del verbo, no delante como en «dos años estudié chino»."}]'::jsonb, '[{"hsk_level":1,"code":"4.6.1"},{"hsk_level":2,"code":"6.3.4"}]'::jsonb),
  (2, '6.1.1', '句子的类型', '句型', '单句', '单句', 'Sujeto + [sujeto 2 + predicado]', 'El predicado es a su vez una frase pequeña con su propio sujeto. En 他身体很好 se habla de «él» y, dentro de él, de su salud: «él está bien de salud». El primer sujeto es el tema y el segundo, la parte concreta de la que se dice algo. Es la forma normal de hablar de salud, aspecto o rasgos de algo: 我头疼, 这个饭馆菜很好吃. No hace falta 有 ni 的.', '[{"zh":"他身体很好。","pinyin":"Tā shēntǐ hěn hǎo.","es":"Él está bien de salud."},{"zh":"我今天头疼。","pinyin":"Wǒ jīntiān tóu téng.","es":"Hoy me duele la cabeza."},{"zh":"这个饭馆菜很好吃。","pinyin":"Zhège fànguǎn cài hěn hǎochī.","es":"En este restaurante la comida está muy rica."},{"zh":"我工作很忙。","pinyin":"Wǒ gōngzuò hěn máng.","es":"Estoy muy ocupado con el trabajo."},{"zh":"我妈妈身体不太好。","pinyin":"Wǒ māma shēntǐ bú tài hǎo.","es":"Mi madre no está muy bien de salud."}]'::jsonb, array['主谓句4：主谓谓语句']::text[], 43, array['身体', '头疼', '菜很好吃', '工作很忙']::text[], '[{"wrong":"我有头疼。","right":"我头疼。","why":"En chino no se «tiene» dolor de cabeza: la parte del cuerpo es el sujeto de su propio predicado."}]'::jsonb, '[{"hsk_level":1,"code":"3.1.1"}]'::jsonb),
  (2, '6.2.1', '句子的类型', '句类', '疑问句', '疑问句', '(是) A 还是 B？', 'Para preguntar entre dos opciones se unen con 还是: 你要大的还是小的？ La pregunta ya está hecha, así que no lleva 吗. Si las opciones son acciones, se repite el verbo (你今天去还是明天去？) y se puede poner 是 delante de la primera. En las afirmaciones la «o» no es 还是, sino 或者.', '[{"zh":"你要大的还是小的？","pinyin":"Nǐ yào dà de háishi xiǎo de?","es":"¿Quieres el grande o el pequeño?"},{"zh":"你今天去还是明天去？","pinyin":"Nǐ jīntiān qù háishi míngtiān qù?","es":"¿Vas hoy o mañana?"},{"zh":"他是老师还是学生？","pinyin":"Tā shì lǎoshī háishi xuésheng?","es":"¿Es profesor o estudiante?"},{"zh":"你是坐地铁来的还是打车来的？","pinyin":"Nǐ shì zuò dìtiě lái de háishi dǎchē lái de?","es":"¿Has venido en metro o en taxi?"}]'::jsonb, array['用“还是”连接的选择问句']::text[], 44, array['还是']::text[], '[{"wrong":"你喝茶或者咖啡？","right":"你喝茶还是咖啡？","why":"En una pregunta entre dos opciones la «o» es 还是; 或者 es la «o» de las afirmaciones."}]'::jsonb, '[{"hsk_level":1,"code":"5.2.2"},{"hsk_level":2,"code":"2.9.2"}]'::jsonb),
  (2, '6.2.2', '句子的类型', '句类', '祈使句', '祈使句', '(你 / 请) + 别 + verbo (+ 了 / 吧)', 'Una orden negativa se forma con 别 delante del verbo: 别走. Con 了 al final pide dejar algo que ya está pasando: 别玩手机了 «deja el móvil». Para sonar más amable se pone 请 delante: 请别在这儿说话. 不要 expresa lo mismo con un tono algo más firme; con 不 solo no se puede prohibir.', '[{"zh":"别玩手机了，快吃饭吧。","pinyin":"Bié wán shǒujī le, kuài chī fàn ba.","es":"Deja el móvil y come."},{"zh":"请别在这儿说话。","pinyin":"Qǐng bié zài zhèr shuōhuà.","es":"Por favor, no habléis aquí."},{"zh":"别忘了明天的考试。","pinyin":"Bié wàng le míngtiān de kǎoshì.","es":"No olvides el examen de mañana."},{"zh":"你别走，我们一起吃饭吧。","pinyin":"Nǐ bié zǒu, wǒmen yìqǐ chī fàn ba.","es":"No te vayas, comamos juntos."}]'::jsonb, array['用“别”的祈使句']::text[], 45, array['别']::text[], '[{"wrong":"你不说话！","right":"你别说话！","why":"Con 不 solo se describe lo que alguien hace; para prohibir se usa 别 o 不要."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.5"},{"hsk_level":1,"code":"5.2.3"}]'::jsonb),
  (2, '6.3.1', '句子的类型', '特殊句式', '“是”字句2', '“是”字句2', 'Sujeto + 是 + descripción + 的 · 不是…，是…', 'Además de identificar (我是学生), 是 sirve para explicar cómo es algo: 这本书是新的, 我的手机是黑色的. La descripción suele cerrar con 的 porque se omite el nombre: «es (uno) nuevo». También aclara o corrige una situación: 我不是不想去，是没有时间 «no es que no quiera ir, es que no tengo tiempo».', '[{"zh":"这本书是新的。","pinyin":"Zhè běn shū shì xīn de.","es":"Este libro es nuevo."},{"zh":"我的手机是黑色的。","pinyin":"Wǒ de shǒujī shì hēisè de.","es":"Mi móvil es negro."},{"zh":"我不是不想去，是没有时间。","pinyin":"Wǒ bú shì bù xiǎng qù, shì méiyǒu shíjiān.","es":"No es que no quiera ir, es que no tengo tiempo."},{"zh":"这件衣服是妈妈的。","pinyin":"Zhè jiàn yīfu shì māma de.","es":"Esta ropa es de mamá."}]'::jsonb, array['表示说明或特征']::text[], 46, array['是']::text[], '[{"wrong":"这本书是新。","right":"这本书是新的。","why":"Si describes con 是 + adjetivo, cierra con 的 (是新的); sin 是 basta con 很: 这本书很新."}]'::jsonb, '[{"hsk_level":1,"code":"5.3.1"}]'::jsonb),
  (2, '6.3.2', '句子的类型', '特殊句式', '“有”字句2', '“有”字句2', 'Sujeto + 有 + cantidad / B (+ 这么 / 那么) + adjetivo', '有 seguido de una medida indica que algo llega a ella: 从我家到学校有一个小时 «hay una hora», 他有二十岁了 «ya tiene sus veinte años». Con otra persona o cosa compara si se alcanza su nivel: 你有他这么高吗？ «¿eres tan alto como él?». En español usamos «medir», «llegar a» o «tan… como»; en chino basta con 有.', '[{"zh":"你有他这么高吗？","pinyin":"Nǐ yǒu tā zhème gāo ma?","es":"¿Eres tan alto como él?"},{"zh":"他今年有二十岁了吧？","pinyin":"Tā jīnnián yǒu èrshí suì le ba?","es":"Este año ya tiene sus veinte, ¿no?"},{"zh":"这个房间有那个房间大吗？","pinyin":"Zhège fángjiān yǒu nàge fángjiān dà ma?","es":"¿Esta habitación es tan grande como aquella?"},{"zh":"从我家到学校有一个小时。","pinyin":"Cóng wǒ jiā dào xuéxiào yǒu yí gè xiǎoshí.","es":"De mi casa al colegio hay una hora."}]'::jsonb, array['表示达到']::text[], 47, array['有']::text[], '[{"wrong":"你是他这么高吗？","right":"你有他这么高吗？","why":"Para preguntar si algo llega a la medida de otro se usa 有, no 是."}]'::jsonb, '[{"hsk_level":1,"code":"5.3.2"},{"hsk_level":2,"code":"6.3.4"}]'::jsonb),
  (2, '6.3.3', '句子的类型', '特殊句式', '存现句2', '存现句2', 'lugar + verbo + 着 + (número + clasificador) + nombre', 'Para describir qué hay en un sitio y en qué postura, la frase empieza por el lugar y sigue con un verbo con 着: 门口站着一个人 «en la puerta hay un hombre de pie». Lo que hay va al final, casi siempre con número y clasificador, y el lugar no lleva 在 delante. Dice más que 有: además de qué hay, cuenta cómo está.', '[{"zh":"门口站着一个人。","pinyin":"Ménkǒu zhànzhe yí gè rén.","es":"En la puerta hay un hombre de pie."},{"zh":"椅子上坐着一个孩子。","pinyin":"Yǐzi shang zuòzhe yí gè háizi.","es":"En la silla está sentado un niño."},{"zh":"书上写着我的名字。","pinyin":"Shū shang xiězhe wǒ de míngzi.","es":"En el libro está escrito mi nombre."},{"zh":"这个房间里住着两个学生。","pinyin":"Zhège fángjiān li zhùzhe liǎng gè xuésheng.","es":"En esta habitación viven dos estudiantes."}]'::jsonb, array['处所+动词+着(+数量短语)+名词']::text[], 48, array['着']::text[], '[{"wrong":"在门口站着一个人。","right":"门口站着一个人。","why":"En esta construcción el lugar abre la frase sin 在."}]'::jsonb, '[{"hsk_level":1,"code":"5.3.3"},{"hsk_level":2,"code":"7.1.1"}]'::jsonb),
  (2, '6.3.4', '句子的类型', '特殊句式', '比较句1', '比较句1', 'A 比 B + adjetivo (+ diferencia) · A 没有 B (那么) + adjetivo · A + V 得 + 比 B + adjetivo', 'A 比 B + adjetivo dice que A supera a B: 今天比昨天冷. La diferencia va detrás del adjetivo: 高一点儿, 贵多了. Para decir que A no llega a B se usa 没有: 我没有他那么高. Con una acción, 比 va detrás de 得 o delante del verbo: 他跑得比我快. En una comparación el adjetivo nunca lleva 很 ni 非常.', '[{"zh":"今天比昨天冷。","pinyin":"Jīntiān bǐ zuótiān lěng.","es":"Hoy hace más frío que ayer."},{"zh":"他比我高一点儿。","pinyin":"Tā bǐ wǒ gāo yìdiǎnr.","es":"Es un poco más alto que yo."},{"zh":"这个比那个贵多了。","pinyin":"Zhège bǐ nàge guì duō le.","es":"Este es mucho más caro que aquel."},{"zh":"我没有他那么高。","pinyin":"Wǒ méiyǒu tā nàme gāo.","es":"No soy tan alto como él."},{"zh":"他跑得比我快。","pinyin":"Tā pǎo de bǐ wǒ kuài.","es":"Corre más rápido que yo."}]'::jsonb, array['（1）A比B+形容词', '（2）A比B+形容词+数量补语/程度补语', '（3）A有/没有B（+这么/那么）+形容词', '（4）A比B+动词+得+形容词/A+动词+得+比+B+形容词']::text[], 49, array['比', '没有']::text[], '[{"wrong":"我比他不高。","right":"我没有他高。","why":"Para decir que A no supera a B no se pone 不 detrás de 比: se usa 没有."},{"wrong":"今天比昨天很冷。","right":"今天比昨天冷多了。","why":"Con 比 el adjetivo no lleva 很; la diferencia se expresa detrás: 冷多了, 冷一点儿."}]'::jsonb, '[{"hsk_level":2,"code":"2.8.3"},{"hsk_level":2,"code":"5.4.4"}]'::jsonb),
  (2, '6.3.5', '句子的类型', '特殊句式', '“是……的”句1', '“是……的”句1', null, null, '[]'::jsonb, array['强调时间、地点、方式、动作者']::text[], 50, '{}'::text[], '[]'::jsonb, '[]'::jsonb),
  (2, '6.3.6', '句子的类型', '特殊句式', '兼语句1', '兼语句1', null, null, '[]'::jsonb, array['表使令：主语+请/叫/让……+宾语1+动词+宾语2']::text[], 51, '{}'::text[], '[]'::jsonb, '[]'::jsonb),
  (2, '6.3.7', '句子的类型', '特殊句式', '双宾语句2', '双宾语句2', null, null, '[]'::jsonb, array['主语+动词+给+宾语1+宾语2']::text[], 52, '{}'::text[], '[]'::jsonb, '[]'::jsonb),
  (2, '6.4.1', '句子的类型', '复句', '选择复句', '选择复句', null, null, '[]'::jsonb, array['（是）……，还是……']::text[], 53, '{}'::text[], '[]'::jsonb, '[]'::jsonb),
  (2, '6.4.2', '句子的类型', '复句', '转折复句', '转折复句', null, null, '[]'::jsonb, array['虽然……，但是……']::text[], 54, '{}'::text[], '[]'::jsonb, '[]'::jsonb),
  (2, '6.4.3', '句子的类型', '复句', '因果复句', '因果复句', '因为 + causa，所以 + resultado', '因为 presenta la causa y 所以 la consecuencia. Pueden ir los dos o solo uno, pero el orden es fijo: 所以 siempre introduce el resultado. Si quieres dar la causa al final, como el «porque» español, pon 因为 en la segunda parte y ningún 所以: 我没去，因为下雨了.', '[{"zh":"因为下雨，所以我没去。","pinyin":"Yīnwèi xià yǔ, suǒyǐ wǒ méi qù.","es":"Como llovía, no fui."},{"zh":"因为他生病了，所以没来上课。","pinyin":"Yīnwèi tā shēngbìng le, suǒyǐ méi lái shàngkè.","es":"Como estaba enfermo, no vino a clase."},{"zh":"我今天很累，所以想去睡觉。","pinyin":"Wǒ jīntiān hěn lèi, suǒyǐ xiǎng qù shuìjiào.","es":"Hoy estoy muy cansado, así que quiero irme a dormir."},{"zh":"我没去，因为下雨了。","pinyin":"Wǒ méi qù, yīnwèi xià yǔ le.","es":"No fui porque llovía."}]'::jsonb, array['因为……，所以……']::text[], 55, array['因为', '所以']::text[], '[{"wrong":"所以我没去，因为下雨了。","right":"因为下雨，所以我没去。","why":"所以 introduce el resultado y va detrás de la causa; si la causa va al final, se usa solo 因为."}]'::jsonb, '[]'::jsonb),
  (2, '6.4.4', '句子的类型', '复句', '紧缩复句', '紧缩复句', null, null, '[]'::jsonb, array['一……就……']::text[], 56, '{}'::text[], '[]'::jsonb, '[]'::jsonb),
