  ('matching', 3, (select w.id from public.words w where w.hanzi = '关系' and w.pinyin = 'guānxì' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-01","unit_code":"6.3.4","pairs":[{"left":"关系","right":"relación"},{"left":"终于","right":"por fin"},{"left":"根据","right":"según"},{"left":"而且","right":"además"}],"explanation":"«关系» nombra un vínculo, «终于» un resultado tras esperar, «根据» la base de una decisión y «而且» una adición."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '因为' and w.pinyin = 'yīnwèi' and w.hsk_level = 2 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-02","unit_code":"6.3.5","pairs":[{"left":"因为","right":"porque"},{"left":"虽然","right":"aunque"},{"left":"不过","right":"sin embargo"},{"left":"而且","right":"además"}],"explanation":"«因为» causa, «虽然» contraste, «不过» objeción moderada y «而且» información adicional: son conectores distintos."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '需要' and w.pinyin = 'xūyào' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-03","unit_code":"5.1","pairs":[{"left":"需要","right":"necesitar"},{"left":"决定","right":"decidir"},{"left":"问题","right":"pregunta"},{"left":"完成","right":"completar"}],"explanation":"«需要» expresa necesidad, «决定» una elección, «问题» aquello que se pregunta y «完成» el final de una tarea."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '比较' and w.pinyin = 'bǐjiào' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-04","unit_code":"2.5.3","pairs":[{"left":"比较","right":"relativamente"},{"left":"可能","right":"posiblemente"},{"left":"终于","right":"por fin"},{"left":"已经","right":"ya"}],"explanation":"«比较» expresa grado relativo, «可能» posibilidad, «终于» resultado esperado y «已经» anterioridad."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '根据' and w.pinyin = 'gēnjù' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-05","unit_code":"6.3.5","pairs":[{"left":"根据","right":"según"},{"left":"因为","right":"porque"},{"left":"所以","right":"por eso"},{"left":"虽然","right":"aunque"}],"explanation":"«根据» introduce la base, «因为» la causa, «所以» la consecuencia y «虽然» el contraste."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '办法' and w.pinyin = 'bànfǎ' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-06","unit_code":"5.1","pairs":[{"left":"办法","right":"método"},{"left":"问题","right":"pregunta"},{"left":"希望","right":"esperar"},{"left":"重要","right":"importante"}],"explanation":"«办法» es una forma de resolver algo, «问题» lo que necesita solución, «希望» un deseo y «重要» una valoración."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '终于' and w.pinyin = 'zhōngyú' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-01","unit_code":"2.5.3","question":"¿Qué significa 终于?","options":["de repente","por fin","casi","quizá"],"correct":"por fin","explanation":"«终于» señala que algo sucede después de esperar o superar una dificultad; «por fin» conserva ese matiz."}'::jsonb, '"por fin"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '根据' and w.pinyin = 'gēnjù' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-02","unit_code":"2.6.5","question":"¿Qué significa 根据?","options":["según","sin importar","a pesar de","además"],"correct":"según","explanation":"«根据» introduce la información en la que se apoya una decisión; «según» indica esa base."}'::jsonb, '"según"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '虽然' and w.pinyin = 'suīrán' and w.hsk_level = 2 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-03","unit_code":"6.3.5","question":"¿Qué significa 虽然?","options":["aunque","porque","por eso","si"],"correct":"aunque","explanation":"«虽然» presenta una dificultad que no impide lo principal; «aunque» introduce ese contraste."}'::jsonb, '"aunque"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '而且' and w.pinyin = 'érqiě' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-04","unit_code":"6.3.4","question":"¿Qué significa 而且?","options":["además","ya","por fin","quizá"],"correct":"además","explanation":"«而且» añade otra característica o acción además de la anterior; «además» expresa esa suma."}'::jsonb, '"además"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '关系' and w.pinyin = 'guānxì' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-05","unit_code":"5.1","question":"¿Qué significa 关系?","options":["relación","resultado","condición","pregunta"],"correct":"relación","explanation":"«关系» habla del vínculo entre personas o cosas; «relación» nombra ese vínculo."}'::jsonb, '"relación"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '如果' and w.pinyin = 'rúguǒ' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-06","unit_code":"6.3.6","question":"¿Qué significa 如果?","options":["si","según","aunque","por fin"],"correct":"si","explanation":"«如果» plantea una condición para lo que ocurrirá después; «si» introduce esa condición."}'::jsonb, '"si"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '把' and w.pinyin = 'bǎ' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-01","unit_code":"6.2.1","words":["把","请","关上","门"],"correct_order":["请","把","门","关上"],"translation":"请把门关上","explanation":"La petición usa «请 + 把 + objeto + resultado»: «请把门关上» pide cerrar la puerta."}'::jsonb, '"请把门关上"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '把' and w.pinyin = 'bǎ' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-02","unit_code":"6.2.1","words":["做完","他","作业","把","了"],"correct_order":["他","把","作业","做完","了"],"translation":"他把作业做完了","explanation":"La construcción «把» adelanta el objeto y «做完» expresa el resultado: «他把作业做完了» significa que terminó los deberes."}'::jsonb, '"他把作业做完了"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '他' and w.pinyin = 'tā' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-03","unit_code":"2.5.3","words":["到了","他","终于"],"correct_order":["他","终于","到了"],"translation":"他终于到了","explanation":"«终于» va antes del verbo para marcar el resultado esperado: «他终于到了» significa «por fin ha llegado»."}'::jsonb, '"他终于到了"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '虽然' and w.pinyin = 'suīrán' and w.hsk_level = 2 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-04","unit_code":"6.3.5","words":["不好","虽然","天气","还是","去了"],"correct_order":["虽然","天气","不好","还是","去了"],"translation":"虽然天气不好还是去了","explanation":"«虽然» introduce la subordinada y «还是» la principal contra lo esperado: aunque hacía mal tiempo, fuimos."}'::jsonb, '"虽然天气不好还是去了"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '应该' and w.pinyin = 'yīnggāi' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-05","unit_code":"2.5.6","words":["作业","应该","早点","我们","完成"],"correct_order":["我们","应该","早点","完成","作业"],"translation":"我们应该早点完成作业","explanation":"La frase combina sujeto + «应该» + tiempo + verbo + objeto: deberíamos terminar pronto los deberes."}'::jsonb, '"我们应该早点完成作业"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '根据' and w.pinyin = 'gēnjù' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-06","unit_code":"2.6.5","words":["问题","根据","做","决定","我们"],"correct_order":["我们","根据","问题","做","决定"],"translation":"我们根据问题做决定","explanation":"«根据 + referencia» introduce el criterio y después viene la acción: decidimos según el problema."}'::jsonb, '"我们根据问题做决定"'::jsonb, 'seed', null)
insert into public.reading (slug, hsk_level, format, title, topic, series, series_index, sentences, questions, target_words, target_grammar, audio_kind, audio_url)
values
  ('school-01-new-classmate', 2, 'story', '新同学', 'estudio', 'escuela', 1, '[{"zh":"昨天学校来了一个新同学。","pinyin":"Zuótiān xuéxiào lái le yí gè xīn tóngxué.","es":"Ayer llegó un compañero nuevo a la escuela."},{"zh":"老师给我们介绍他的姓名。","pinyin":"Lǎoshī gěi wǒmen jièshào tā de xìngmíng.","es":"El profesor nos presentó su nombre."},{"zh":"老师说他的姓名很好听。","pinyin":"Lǎoshī shuō tā de xìngmíng hěn hǎotīng.","es":"El profesor dice que su nombre suena bien."},{"zh":"我和他坐在一起学习汉语。","pinyin":"Wǒ hé tā zuò zài yìqǐ xuéxí Hànyǔ.","es":"Él y yo nos sentamos juntos a estudiar chino."},{"zh":"下课的时候，我们一起说话。","pinyin":"Xiàkè de shíhou, wǒmen yìqǐ shuōhuà.","es":"Cuando termina la clase, hablamos juntos."},{"zh":"他喜欢看书，也喜欢看电影。","pinyin":"Tā xǐhuan kàn shū, yě xǐhuan kàn diànyǐng.","es":"Le gusta leer y también ver películas."},{"zh":"我觉得认识新朋友很高兴。","pinyin":"Wǒ juéde rènshi xīn péngyou hěn gāoxìng.","es":"Creo que es muy agradable conocer a un amigo nuevo."},{"zh":"明天我还想和他一起去学校。","pinyin":"Míngtiān wǒ hái xiǎng hé tā yìqǐ qù xuéxiào.","es":"Mañana también quiero ir a la escuela con él."}]'::jsonb, '[{"prompt":"新同学喜欢看什么？","options":["水果和茶","书和电影","衣服和咖啡"],"answer_index":1,"evidence_sentence":5},{"prompt":"我和新同学一起做什么？","options":["买东西","看病","学习汉语"],"answer_index":2,"evidence_sentence":3},{"prompt":"新同学明天要去哪里？","options":["学校","商店","医院"],"answer_index":0,"evidence_sentence":7}]'::jsonb, array['新', '同学', '认识']::text[], '[{"code":"6.3.5","level":2}]'::jsonb, 'tts', null),
  ('school-02-forgot-homework', 2, 'dialogue', '为什么没有写字', 'estudio', 'escuela', 2, '[{"zh":"今天老师问我们为什么没有写字。","pinyin":"Jīntiān lǎoshī wèn wǒmen wèishénme méiyǒu xiězì.","es":"Hoy el profesor pregunta por qué no hemos escrito."},{"zh":"同学说因为昨天身体不好，所以没有学习。","pinyin":"Tóngxué shuō yīnwèi zuótiān shēntǐ bù hǎo, suǒyǐ méiyǒu xuéxí.","es":"El compañero dice que ayer no se encontraba bien, así que no estudió."},{"zh":"老师说现在好了吗。","pinyin":"Lǎoshī shuō xiànzài hǎo le ma.","es":"El profesor pregunta si ahora está mejor."},{"zh":"同学说已经好了，但是还想休息。","pinyin":"Tóngxué shuō yǐjīng hǎo le, dànshì hái xiǎng xiūxi.","es":"El compañero dice que ya está mejor, pero aún quiere descansar."},{"zh":"老师让他明天再写字。","pinyin":"Lǎoshī ràng tā míngtiān zài xiězì.","es":"El profesor le pide que escriba mañana."},{"zh":"同学们都希望他回到学校。","pinyin":"Tóngxuémen dōu xīwàng tā huí dào xuéxiào.","es":"Todos los compañeros esperan que vuelva a la escuela."},{"zh":"他会和老师说话。","pinyin":"Tā huì hé lǎoshī shuōhuà.","es":"Él hablará con el profesor."},{"zh":"今天大家一起学习。","pinyin":"Jīntiān dàjiā yìqǐ xuéxí.","es":"Hoy todos estudiamos juntos."}]'::jsonb, '[{"prompt":"同学昨天为什么没有学习？","options":["因为去商店","因为看电影","因为身体不好"],"answer_index":2,"evidence_sentence":1},{"prompt":"同学现在想做什么？","options":["休息","买衣服","踢足球"],"answer_index":0,"evidence_sentence":3},{"prompt":"老师让他什么时候写字？","options":["昨天","明天","今天"],"answer_index":1,"evidence_sentence":4}]'::jsonb, array['因为', '所以', '身体']::text[], '[{"code":"6.4.3","level":2}]'::jsonb, 'tts', null),
  ('shop-01-tea-and-coffee', 2, 'short_text', '去商店买东西', 'compras', 'tienda', 1, '[{"zh":"今天我和朋友去商店买东西。","pinyin":"Jīntiān wǒ hé péngyou qù shāngdiàn mǎi dōngxi.","es":"Hoy mi amigo y yo fuimos a la tienda a comprar cosas."},{"zh":"商店里的水果很多。","pinyin":"Shāngdiàn lǐ de shuǐguǒ hěn duō.","es":"En la tienda hay mucha fruta."},{"zh":"我买了苹果和茶。","pinyin":"Wǒ mǎi le píngguǒ hé chá.","es":"Compré manzanas y té."},{"zh":"朋友买了咖啡。","pinyin":"Péngyou mǎi le kāfēi.","es":"Mi amigo compró café."},{"zh":"咖啡比茶贵。","pinyin":"Kāfēi bǐ chá guì.","es":"El café es más caro que el té."},{"zh":"一个苹果三元，一个咖啡十元。","pinyin":"Yí gè píngguǒ sān yuán, yí gè kāfēi shí yuán.","es":"Una manzana cuesta tres yuanes; un café, diez."},{"zh":"但是朋友说咖啡很好喝。","pinyin":"Dànshì péngyou shuō kāfēi hěn hǎo hē.","es":"Pero mi amigo dice que el café está muy rico."},{"zh":"我觉得茶也很好喝。","pinyin":"Wǒ juéde chá yě hěn hǎo hē.","es":"Yo creo que el té también está muy rico."},{"zh":"我们喝了茶，也吃了苹果。","pinyin":"Wǒmen hē le chá, yě chī le píngguǒ.","es":"Bebimos té y también comimos manzanas."},{"zh":"我很喜欢那个商店。","pinyin":"Wǒ hěn xǐhuan nàge shāngdiàn.","es":"Me gusta mucho esa tienda."}]'::jsonb, '[{"prompt":"咖啡和茶，哪个贵？","options":["茶","咖啡","水果"],"answer_index":1,"evidence_sentence":4},{"prompt":"我买了什么？","options":["苹果和茶","咖啡","水"],"answer_index":0,"evidence_sentence":2},{"prompt":"一个咖啡多少钱？","options":["三元","一元","十元"],"answer_index":2,"evidence_sentence":5}]'::jsonb, array['比', '咖啡', '但是']::text[], '[{"code":"6.3.4","level":2}]'::jsonb, 'tts', null),
  ('market-02-too-expensive', 2, 'dialogue', '这件衣服太贵了', 'compras', 'tienda', 2, '[{"zh":"今天我和朋友一起买新衣服。","pinyin":"Jīntiān wǒ hé péngyou yìqǐ mǎi xīn yīfu.","es":"Hoy mi amigo y yo vamos a comprar ropa nueva."},{"zh":"他问商店里的衣服多少钱。","pinyin":"Tā wèn shāngdiàn lǐ de yīfu duōshao qián.","es":"Pregunta cuánto cuesta la ropa de la tienda."},{"zh":"先生说这件衣服太贵了。","pinyin":"Xiānsheng shuō zhè jiàn yīfu tài guì le.","es":"El señor dice que esta prenda es demasiado cara."},{"zh":"朋友觉得那个颜色很好看。","pinyin":"Péngyou juéde nàge yánsè hěn hǎokàn.","es":"A mi amigo le parece muy bonito ese color."},{"zh":"但是他没有很多钱。","pinyin":"Dànshì tā méiyǒu hěn duō qián.","es":"Pero no tiene mucho dinero."},{"zh":"先生说那件便宜一些。","pinyin":"Xiānsheng shuō nà jiàn piányi yìxiē.","es":"El señor dice que aquella es algo más barata."},{"zh":"朋友看了看，还是觉得太贵。","pinyin":"Péngyou kàn le kàn, háishi juéde tài guì.","es":"Mi amigo la mira y sigue pensando que es demasiado cara."},{"zh":"朋友买了一件便宜的衣服。","pinyin":"Péngyou mǎi le yí jiàn piányi de yīfu.","es":"Mi amigo compra una prenda barata."},{"zh":"明天他还来这个商店买东西。","pinyin":"Míngtiān tā hái lái zhège shāngdiàn mǎi dōngxi.","es":"Mañana volverá a esta tienda a comprar cosas."}]'::jsonb, '[{"prompt":"朋友觉得衣服怎么样？","options":["很好吃","太贵","很冷"],"answer_index":1,"evidence_sentence":6},{"prompt":"朋友最后买了什么？","options":["咖啡","水果","一件便宜的衣服"],"answer_index":2,"evidence_sentence":7},{"prompt":"朋友明天还要去哪里？","options":["这个商店","学校","医院"],"answer_index":0,"evidence_sentence":8}]'::jsonb, array['太', '贵', '便宜']::text[], '[{"code":"2.6.1","level":1}]'::jsonb, 'tts', null),
  ('market-03-buying-fruit', 2, 'short_text', '买水果', 'compras', 'tienda', 3, '[{"zh":"今天我和朋友去商店买水果。","pinyin":"Jīntiān wǒ hé péngyou qù shāngdiàn mǎi shuǐguǒ.","es":"Hoy mi amigo y yo vamos a la tienda a comprar fruta."},{"zh":"我们看了苹果，也看了肉。","pinyin":"Wǒmen kàn le píngguǒ, yě kàn le ròu.","es":"Miramos las manzanas y también la carne."},{"zh":"朋友说苹果很好吃，但是肉太贵。","pinyin":"Péngyou shuō píngguǒ hěn hǎochī, dànshì ròu tài guì.","es":"Mi amigo dice que las manzanas están muy ricas, pero la carne es demasiado cara."},{"zh":"我问一个苹果多少元。","pinyin":"Wǒ wèn yí gè píngguǒ duōshao yuán.","es":"Pregunto cuántos yuanes cuesta una manzana."},{"zh":"先生说一个苹果三元，三个苹果八元。","pinyin":"Xiānsheng shuō yí gè píngguǒ sān yuán, sān gè píngguǒ bā yuán.","es":"El señor dice que una manzana cuesta tres yuanes y tres cuestan ocho."},{"zh":"我们买了三个苹果和两个包子。","pinyin":"Wǒmen mǎi le sān gè píngguǒ hé liǎng gè bāozi.","es":"Compramos tres manzanas y dos bollos."},{"zh":"回家的时候，我很高兴。","pinyin":"Huí jiā de shíhou, wǒ hěn gāoxìng.","es":"Cuando volvemos a casa, estoy muy contento."},{"zh":"晚上我们一起吃水果。","pinyin":"Wǎnshang wǒmen yìqǐ chī shuǐguǒ.","es":"Por la noche comemos fruta juntos."}]'::jsonb, '[{"prompt":"三个苹果多少钱？","options":["三元","八元","十元"],"answer_index":1,"evidence_sentence":4},{"prompt":"他们买了几个苹果？","options":["一个","两个","三个"],"answer_index":2,"evidence_sentence":5},{"prompt":"朋友觉得肉怎么样？","options":["太贵","很好听","很冷"],"answer_index":0,"evidence_sentence":2}]'::jsonb, array['苹果', '水果', '买']::text[], '[{"code":"5.4.4","level":2}]'::jsonb, 'tts', null),
  ('health-01-i-feel-bad', 2, 'dialogue', '身体不太好', 'salud', null, null, '[{"zh":"今天早上我觉得身体不太好。","pinyin":"Jīntiān zǎoshang wǒ juéde shēntǐ bú tài hǎo.","es":"Esta mañana no me encontraba muy bien."},{"zh":"我告诉妈妈我的头有一点儿疼。","pinyin":"Wǒ gàosu māma wǒ de tóu yǒu yìdiǎnr téng.","es":"Le digo a mamá que me duele un poco la cabeza."},{"zh":"妈妈和我去医院看医生。","pinyin":"Māma hé wǒ qù yīyuàn kàn yīshēng.","es":"Mamá y yo vamos al hospital a ver al médico."},{"zh":"医生说我多喝水，也要休息。","pinyin":"Yīshēng shuō wǒ duō hē shuǐ, yě yào xiūxi.","es":"El médico dice que debo beber más agua y descansar."},{"zh":"他给我一些药。","pinyin":"Tā gěi wǒ yìxiē yào.","es":"Me da algo de medicina."},{"zh":"虽然我不想休息，但是妈妈说身体很好。","pinyin":"Suīrán wǒ bù xiǎng xiūxi, dànshì māma shuō shēntǐ hěn hǎo.","es":"Aunque no quiero descansar, mamá dice que mi cuerpo está bien."},{"zh":"下午我吃了药，已经好一点儿了。","pinyin":"Xiàwǔ wǒ chī le yào, yǐjīng hǎo yìdiǎnr le.","es":"Por la tarde tomo la medicina y ya estoy algo mejor."}]'::jsonb, '[{"prompt":"我哪里疼？","options":["手","头","眼睛"],"answer_index":1,"evidence_sentence":1},{"prompt":"医生让我做什么？","options":["喝水和休息","看电影","买衣服"],"answer_index":0,"evidence_sentence":3},{"prompt":"谁给我药？","options":["爸爸","朋友","医生"],"answer_index":2,"evidence_sentence":4}]'::jsonb, array['身体', '药', '休息']::text[], '[{"code":"6.4.2","level":2}]'::jsonb, 'tts', null),
  ('home-01-morning', 2, 'short_text', '早上的生活', 'vida diaria', null, null, '[{"zh":"星期天我六点起床。","pinyin":"Xīngqītiān wǒ liù diǎn qǐchuáng.","es":"El domingo me levanto a las seis."},{"zh":"妈妈在房间做饭，爸爸在房间看书。","pinyin":"Māma zài fángjiān zuòfàn, bàba zài fángjiān kàn shū.","es":"Mamá cocina en la habitación y papá lee en la habitación."},{"zh":"我喝了水，也吃了鸡蛋和面包。","pinyin":"Wǒ hē le shuǐ, yě chī le jīdàn hé miànbāo.","es":"Bebo agua y también como huevos y pan."},{"zh":"中午回家的时候，妈妈已经做好了午饭。","pinyin":"Zhōngwǔ huí jiā de shíhou, māma yǐjīng zuò hǎo le wǔfàn.","es":"Al volver a casa al mediodía, mamá ya ha preparado el almuerzo."},{"zh":"晚上我们一起说今天的事情。","pinyin":"Wǎnshang wǒmen yìqǐ shuō jīntiān de shìqing.","es":"Por la noche hablamos juntos de lo que ha pasado hoy."},{"zh":"我觉得今天很好。","pinyin":"Wǒ juéde jīntiān hěn hǎo.","es":"Creo que hoy ha sido un buen día."},{"zh":"晚上我看看书，也喝茶。","pinyin":"Wǎnshang wǒ kànkan shū, yě hē chá.","es":"Por la noche leo un poco y también bebo té."},{"zh":"星期天大家都不忙。","pinyin":"Xīngqītiān dàjiā dōu bù máng.","es":"El domingo nadie está ocupado."}]'::jsonb, '[{"prompt":"我几点起床？","options":["八点","十点","六点"],"answer_index":2,"evidence_sentence":0},{"prompt":"谁在房间看书？","options":["爸爸","妈妈","老师"],"answer_index":0,"evidence_sentence":1},{"prompt":"妈妈做好了什么？","options":["晚饭","午饭","咖啡"],"answer_index":1,"evidence_sentence":3}]'::jsonb, array['起床', '做饭', '事情']::text[], '[{"code":"2.2.1","level":2}]'::jsonb, 'tts', null),
  ('home-02-cooking', 2, 'story', '一起做饭', 'vida diaria', null, null, '[{"zh":"今天妈妈在房间做饭。","pinyin":"Jīntiān māma zài fángjiān zuòfàn.","es":"Hoy mamá cocina en la habitación."},{"zh":"妈妈坐在桌子旁边，手里拿着茶。","pinyin":"Māma zuò zài zhuōzi pángbiān, shǒu lǐ ná zhe chá.","es":"Mamá se sienta junto a la mesa y sostiene té en la mano."},{"zh":"爸爸在桌子旁边看书。","pinyin":"Bàba zài zhuōzi pángbiān kàn shū.","es":"Papá lee junto a la mesa."},{"zh":"我也给大家做饭，也给大家喝水。","pinyin":"Wǒ yě gěi dàjiā zuòfàn, yě gěi dàjiā hē shuǐ.","es":"Yo también cocino para todos y les doy agua para beber."},{"zh":"饭做好了，我们一起吃饭。","pinyin":"Fàn zuò hǎo le, wǒmen yìqǐ chīfàn.","es":"La comida está lista y comemos juntos."},{"zh":"虽然今天很忙，但是我们都很高兴。","pinyin":"Suīrán jīntiān hěn máng, dànshì wǒmen dōu hěn gāoxìng.","es":"Aunque hoy estamos muy ocupados, estamos todos contentos."},{"zh":"吃完饭，我现在去睡觉。","pinyin":"Chī wán fàn, wǒ xiànzài qù shuìjiào.","es":"Después de comer, ahora me voy a dormir."},{"zh":"爸爸也很高兴。","pinyin":"Bàba yě hěn gāoxìng.","es":"Papá también está muy contento."}]'::jsonb, '[{"prompt":"妈妈手里拿着什么？","options":["书","茶","水"],"answer_index":1,"evidence_sentence":1},{"prompt":"谁在桌子旁边看书？","options":["妈妈","我","爸爸"],"answer_index":2,"evidence_sentence":2},{"prompt":"他们什么时候一起吃饭？","options":["饭做好以后","吃饭以前","明天"],"answer_index":0,"evidence_sentence":4}]'::jsonb, array['着', '虽然', '高兴']::text[], '[{"code":"7.1.1","level":2}]'::jsonb, 'tts', null),
  ('leisure-01-weekend-plan', 2, 'short_text', '星期天看电影', 'ocio', null, null, '[{"zh":"星期天我没有课，想和朋友一起看电影。","pinyin":"Xīngqītiān wǒ méiyǒu kè, xiǎng hé péngyou yìqǐ kàn diànyǐng.","es":"El domingo no tengo clase y quiero ver una película con mi amigo."},{"zh":"我们在家里吃饭，再坐地铁去电影院。","pinyin":"Wǒmen zài jiā lǐ chīfàn, zài zuò dìtiě qù diànyǐngyuàn.","es":"Comemos en casa y después vamos al cine en metro."},{"zh":"朋友说这个电影很好看，但是时间有一点儿晚。","pinyin":"Péngyou shuō zhège diànyǐng hěn hǎokàn, dànshì shíjiān yǒu yìdiǎnr wǎn.","es":"Mi amigo dice que esta película es muy bonita, pero la hora es algo tarde."},{"zh":"电影完了，我们在外边喝茶。","pinyin":"Diànyǐng wán le, wǒmen zài wàibian hē chá.","es":"Cuando termina la película, tomamos té fuera."},{"zh":"我觉得和朋友一起做事很快乐。","pinyin":"Wǒ juéde hé péngyou yìqǐ zuò shì hěn kuàilè.","es":"Creo que hacer cosas con amigos es muy divertido."},{"zh":"晚上回到家，我给妈妈打电话。","pinyin":"Wǎnshang huí dào jiā, wǒ gěi māma dǎ diànhuà.","es":"Por la noche vuelvo a casa y llamo a mamá."},{"zh":"我们还一起看书。","pinyin":"Wǒmen hái yìqǐ kàn shū.","es":"También leemos juntos."}]'::jsonb, '[{"prompt":"他们怎么去电影院？","options":["坐飞机","走路","坐地铁"],"answer_index":2,"evidence_sentence":1},{"prompt":"朋友觉得电影怎么样？","options":["很好看","很冷","太贵"],"answer_index":0,"evidence_sentence":2},{"prompt":"我晚上给谁打电话？","options":["老师","妈妈","朋友"],"answer_index":1,"evidence_sentence":5}]'::jsonb, array['电影', '一起', '快乐']::text[], '[{"code":"6.4.4","level":2}]'::jsonb, 'tts', null),
  ('travel-01-asking-the-way', 2, 'dialogue', '怎么去车站', 'lugares', null, null, '[{"zh":"我今天来到这里，不知道车站怎么走。","pinyin":"Wǒ jīntiān lái dào zhèlǐ, bù zhīdào chēzhàn zěnme zǒu.","es":"Hoy he venido aquí, pero no sé cómo llegar a la estación."},{"zh":"我问一个人地铁站在哪里。","pinyin":"Wǒ wèn yí gè rén dìtiě zhàn zài nǎlǐ.","es":"Le pregunto a una persona dónde está la estación de metro."},{"zh":"他说右边有一个地铁站。","pinyin":"Tā shuō yòubian yǒu yí gè dìtiě zhàn.","es":"Dice que hay una estación de metro a la derecha."},{"zh":"过了饭店，我就看见了车站。","pinyin":"Guò le fàndiàn, wǒ jiù kànjiàn le chēzhàn.","es":"Después de pasar el restaurante, veo la estación."},{"zh":"我说谢谢，他就走了。","pinyin":"Wǒ shuō xièxie, tā jiù zǒu le.","es":"Digo gracias y él se va."},{"zh":"到了车站，我买了票。","pinyin":"Dào le chēzhàn, wǒ mǎi le piào.","es":"Al llegar a la estación, compro un billete."},{"zh":"这次我没有走错路。","pinyin":"Zhè cì wǒ méiyǒu zǒu cuò lù.","es":"Esta vez no me equivoco de camino."},{"zh":"朋友从后面走过来。","pinyin":"Péngyou cóng hòumiàn zǒu guòlái.","es":"Mi amigo se acerca desde atrás."},{"zh":"我觉得走路很好。","pinyin":"Wǒ juéde zǒulù hěn hǎo.","es":"Creo que caminar está muy bien."}]'::jsonb, '[{"prompt":"地铁站在哪里？","options":["后面","右边","商店里"],"answer_index":1,"evidence_sentence":2},{"prompt":"我到了车站以后买了什么？","options":["衣服","药","票"],"answer_index":2,"evidence_sentence":5},{"prompt":"谁走过来了？","options":["朋友","老师","医生"],"answer_index":0,"evidence_sentence":7}]'::jsonb, array['地铁', '车站', '走']::text[], '[{"code":"5.4.2","level":2}]'::jsonb, 'tts', null)
